def _central_route_permission(path, method, role):
    """Permission fallbacks for the small set of school routes lacking local guards."""
    path = str(path or "").rstrip("/") or "/"
    method = str(method or "GET").upper()
    role = str(role or "").lower()
    if path == "/app":
        return {"teacher": "teacher_portal.view", "parent": "parent_portal.view",
                "student": "student_portal.view", "accountant": "accountant_portal.view"}.get(role)
    if path.startswith("/app/portals"):
        return "settings.manage"
    if path.startswith("/app/academics/marks-corrections") or path.endswith("/academics/marks/request-correction"):
        return "marks.edit"
    if path.startswith("/app/academics/external-analysis"):
        return "reports.edit" if method == "POST" else "reports.view"
    if path == "/app/academics/analysis" or path.startswith("/app/academics/marksheet-analysis"):
        return "reports.view"
    if path == "/app/users/add" or path == "/app/users":
        return "users.manage"
    if path == "/app/accounting/expense":
        return "accountant_portal.view"
    if path.startswith("/app/accounting"):
        return "accountant_portal.view"
    return None

class SchoolPermissionRoute(APIRoute):
    """Apply central server-side permission checks, including legacy endpoints."""
    def get_route_handler(self):
        original_handler = super().get_route_handler()

        async def permission_guarded_handler(request: Request):
            role = str(request.session.get("role") or "").lower()
            path = str(request.url.path or "").rstrip("/") or "/"
            method = str(request.method or "GET").upper()
            # Non-administrator accounts are confined to their own portal routes.
            # This prevents direct URL access to school administration modules.
            if role == "teacher":
                teacher_routes = {
                    ("GET", "/app"), ("GET", "/app/class-teacher"),
                    ("GET", "/app/class-monitoring"), ("POST", "/app/class-monitoring/follow-up"),
                    ("GET", "/app/teacher-performance"), ("GET", "/app/teacher-performance/learners"),
                    ("GET", "/app/academics/marks"), ("POST", "/app/academics/marks/save"),
                    ("POST", "/app/academics/marks/save-draft"),
                    ("GET", "/app/academics/marks/request-correction"),
                    ("POST", "/app/academics/marks/request-correction"),
                    ("GET", "/app/academics/marksheets"), ("GET", "/app/academics/marksheets/csv"),
                    ("GET", "/app/academics/marksheets/pdf"),
                    ("GET", "/app/timetable/my"),
                }
                if (method, path) not in teacher_routes:
                    return HTMLResponse("This page is outside the Teacher Portal permissions.",403)
            elif role == "parent":
                if (method, path) not in {("GET", "/app"), ("GET", "/app/parent"), ("POST", "/app/parent/message"), ("GET", "/app/timetable/my")}:
                    return HTMLResponse("This page is outside the Parent Portal permissions.",403)
            elif role == "accountant":
                if (method, path) not in {("GET", "/app"), ("GET", "/app/accounting"), ("POST", "/app/accounting/expense")}:
                    return HTMLResponse("This page is outside the Accountant Portal permissions.",403)
            elif role == "student":
                if (method, path) not in {("GET", "/app"), ("GET", "/app/timetable/my")}:
                    return HTMLResponse("The Student Portal is not yet available.",403)
            required = _central_route_permission(
                request.url.path, request.method, request.session.get("role", "")
            )
            if required:
                school_id = _school_session(request)
                required_permissions = required if isinstance(required, (tuple, list)) else (required,)
                if school_id and any(not _require_permission(request, school_id, permission) for permission in required_permissions):
                    return HTMLResponse(
                        "Access to this portal feature has been restricted by your school administrator.",
                        status_code=403,
                    )
            return await original_handler(request)

        return permission_guarded_handler


router = APIRouter(route_class=SchoolPermissionRoute)

