@router.get("/app/staff", response_class=HTMLResponse)
def staff_page(request: Request, staff: str="", department: str="", role: str="", employment_type: str="", status: str=""):
    sid=_school_session(request)
    if not sid:return RedirectResponse("/")
    staff_tab_id=str(request.query_params.get("ds_tab") or request.scope.get("davischool_tab_id") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_-]{16,64}",staff_tab_id):staff_tab_id=""
    staff_add_action="/app/staff/add"+(("?ds_tab="+quote(staff_tab_id,safe="")) if staff_tab_id else "")
    if not _require_permission(request,sid,"staff.view"):return HTMLResponse("You do not have permission to view staff records.",403)
    q=str(staff or "").strip();dept=str(department or "").strip();desig=str(role or "").strip();emp=str(employment_type or "").strip();state=str(status or "").strip().lower()
    con=_db();cur=con.cursor()
    departments=cur.execute("SELECT DISTINCT department FROM teachers WHERE school_id=? AND coalesce(department,'')<>'' ORDER BY department",(sid,)).fetchall()
    sql="SELECT * FROM teachers WHERE school_id=? AND lower(coalesce(status,'active'))<>'left'";params=[sid]
    if q:
        sql+=" AND (lower(coalesce(name,'')) LIKE ? OR lower(coalesce(tsc_no,'')) LIKE ? OR lower(coalesce(email,'')) LIKE ? OR lower(coalesce(phone,'')) LIKE ?)"
        term="%"+q.casefold()+"%";params.extend([term]*4)
    if dept:sql+=" AND department=?";params.append(dept)
    if desig:sql+=" AND role=?";params.append(desig)
    if emp:sql+=" AND employment_type=?";params.append(emp)
    if state:sql+=" AND lower(coalesce(status,'active'))=?";params.append(state)
    sql+=" ORDER BY name";staff_rows=cur.execute(sql,params).fetchall();con.close()
    def val(t,k,d=""):
        try:return str(t[k] if t[k] is not None else d)
        except Exception:return d
    def staff_group_for(person):
        designation=val(person,"role","").strip().casefold()
        admin_designations={"school administrator","registrar","accountant / bursar"}
        teaching_designations={"teacher"}
        if designation in admin_designations:
            return "administration"
        if designation in teaching_designations or "teacher" in designation or "head of department" in designation:
            return "teaching"
        return "support"
    staff_group_counts={"all":len(staff_rows),"teaching":0,"administration":0,"support":0}
    for person in staff_rows:
        staff_group_counts[staff_group_for(person)]+=1
    rows="".join(f"""<tr data-staff-group='{staff_group_for(t)}'><td><b>{escape(val(t,'name'))}</b><div class='muted'>{escape(val(t,'tsc_no'))}</div></td><td>{escape(val(t,'role'))}</td><td>{escape(val(t,'department') or '—')}</td><td>{escape(val(t,'email') or '—')}</td><td>{escape(val(t,'phone') or '—')}</td><td>{escape(val(t,'employment_type'))}</td><td><span class='status'>{escape(val(t,'status','active').replace('_',' ').title())}</span></td><td><a class='action' href='/app/staff/edit/{int(t['id'])}?'+{json.dumps(('ds_tab='+quote(staff_tab_id,safe='')) if staff_tab_id else '')} onclick="if(typeof openStaffEdit==='function'){{openStaffEdit(this.href+(this.href.includes('?')?'&':'?')+'modal=1');return false;}}">Edit</a></td></tr>""" for t in staff_rows)
    gender_counts={"Male":0,"Female":0}
    role_counts={}
    for person in staff_rows:
        gender_value=val(person,"gender").strip().title()
        if gender_value in ("Male","Female"):
            gender_counts[gender_value]+=1
        role_value=val(person,"role","Unassigned").strip() or "Unassigned"
        role_counts[role_value]=role_counts.get(role_value,0)+1
    active_count=sum(1 for person in staff_rows if val(person,"status","active").strip().lower()=="active")
    teaching_count=sum(1 for person in staff_rows if "teacher" in val(person,"role").lower())
    support_count=max(0,len(staff_rows)-teaching_count)
    role_cards="".join(f"<div class='staff-kpi'><span>{escape(label)}</span><strong>{count}</strong><small>In current results</small></div>" for label,count in sorted(role_counts.items(),key=lambda item:(-item[1],item[0].lower())) if label.strip().lower() not in ("teacher","teachers"))[:3]
    dept_opts="<option value=''>All departments</option>"+"".join(f"<option value='{escape(str(d['department']),quote=True)}' {'selected' if str(d['department'])==dept else ''}>{escape(str(d['department']))}</option>" for d in departments)
    roles=list(STAFF_DESIGNATION_OPTIONS)
    role_opts="<option value=''>All designations</option>"+"".join(f"<option {'selected' if x==desig else ''}>{x}</option>" for x in roles)
    emp_opts="<option value=''>All employment types</option>"+"".join(f"<option {'selected' if x==emp else ''}>{x}</option>" for x in ["Permanent","Contract","Part-time"])
    state_opts="".join(f"<option value='{v}' {'selected' if state==v else ''}>{label}</option>" for v,label in [("","All statuses"),("active","Active"),("inactive","Inactive"),("on_leave","On Leave")])
    body=f"""<div class='page students-list-page staff-manager-page'><div class='page-heading'><div><div class='staff-eyebrow'>STAFF MANAGER / DIRECTORY</div><h1>Staff List</h1><div class='muted'>A clear, organised directory for your teachers and support team.</div></div><div class='staff-page-actions'><button type='button' class='btn no-print' onclick="document.getElementById('find-staff-dialog').showModal()">Find Staff</button></div></div>
<div class='staff-kpis staff-directory-kpis'><div class='staff-kpi'><span>Active staff</span><strong>{active_count}</strong><small>Currently active</small></div><div class='staff-kpi'><span>Teaching team</span><strong>{teaching_count}</strong><small>Teaching designations</small></div><div class='staff-kpi'><span>Support & administration</span><strong>{support_count}</strong><small>Other designations</small></div><div class='staff-kpi staff-gender-kpi'><span>Gender distribution</span><div class='staff-gender-counts'><div><strong>{gender_counts["Male"]}</strong><small>Male</small></div><div><strong>{gender_counts["Female"]}</strong><small>Female</small></div></div><div class='staff-gender-bar'><i style='width:{(gender_counts["Male"]*100/max(1,gender_counts["Male"]+gender_counts["Female"])):.1f}%'></i><i style='width:{(gender_counts["Female"]*100/max(1,gender_counts["Male"]+gender_counts["Female"])):.1f}%'></i></div></div>{role_cards}</div>
<button type='button' class='staff-add-panel no-print' onclick="document.getElementById('add-staff-dialog').showModal()"><span><b>Add a staff member</b><small>Enter the staff member's details to create a new staff record</small></span><span class='staff-add-chevron' aria-hidden='true'>＋</span></button>
<dialog id='add-staff-dialog' class='staff-add-dialog'><div class='staff-dialog-heading'><div><div class='staff-eyebrow'>STAFF MANAGER / NEW RECORD</div><h2>Add a staff member</h2><p class='muted'>Enter the staff member's details below.</p></div><button type='button' class='staff-dialog-close' aria-label='Close' onclick="document.getElementById('add-staff-dialog').close()">×</button></div><form method='post' action='{staff_add_action}' class='staff-filters staff-add-form'><label>Full name<input name='name' required placeholder='Full name' class='field'></label><label>Email address<input name='email' type='email' placeholder='Email address' class='field'></label><label>Phone number<input name='phone' placeholder='Phone number' class='field'></label><label>TSC number<input name='tsc_no' placeholder='TSC number' class='field'></label><label>ID number<input name='id_no' placeholder='ID number' class='field'></label><label>Designation<select name='role' id='staffAddRole' class='field' onchange="filterStaffDepartment('staffAddRole','staffAddDepartment')">{''.join(f"<option value='{escape(x,quote=True)}'>{escape(x)}</option>" for x in STAFF_DESIGNATION_OPTIONS)}</select></label><label>Gender<select name='gender' class='field'><option value=''>Select gender</option><option>Male</option><option>Female</option><option>Other</option></select></label><label>Employment type<select name='employment_type' class='field'><option>Permanent</option><option>Contract</option><option>Part-time</option></select></label><label>Status<select name='status' class='field'><option value='active'>Active</option><option value='inactive'>Inactive</option><option value='on_leave'>On Leave</option><option value='left'>Left School</option></select></label><label>Department<select name='department' id='staffAddDepartment' class='field'><option value=''>Select department</option></select></label><div class='staff-dialog-actions'><button type='button' class='btn btn-light' onclick="document.getElementById('add-staff-dialog').close()">Cancel</button><button class='btn'>Save Staff Member</button></div></form></dialog><dialog id='edit-staff-dialog' class='staff-add-dialog staff-edit-dialog'><div id='staff-edit-content' class='staff-edit-content'></div></dialog><script>function openStaffEdit(url){{const dialog=document.getElementById('edit-staff-dialog'),content=document.getElementById('staff-edit-content');content.innerHTML='';fetch(url,{{credentials:'same-origin',headers:{{'X-Requested-With':'XMLHttpRequest'}}}}).then(async r=>{{const html=await r.text();if(!r.ok)throw new Error('Unable to load staff form (HTTP '+r.status+'). '+html.replace(/<[^>]*>/g,' ').trim().slice(0,500));const doc=new DOMParser().parseFromString(html,'text/html');content.innerHTML=doc.body.innerHTML||html;doc.querySelectorAll('script').forEach(old=>{{const s=document.createElement('script');s.textContent=old.textContent;content.appendChild(s);}});dialog.showModal();}}).catch(e=>{{content.innerHTML='<div class="edit-load-error">'+String(e.message).replace(/[&<>]/g,ch=>({{'&':'&amp;','<':'&lt;','>':'&gt;'}}[ch]))+'</div>';dialog.showModal();}});}}function filterStaffDepartment(roleId,departmentId,selectedValue){{
 const role=(document.getElementById(roleId)?.value||'').trim().toLowerCase();
 const teachingRoles=['teacher'];
 const teachingDepartments=['ECDE / Early Childhood Education','Lower Primary','Upper Primary','Junior School','Senior School','Languages','Mathematics','Sciences','Humanities & Social Sciences','Technical & Vocational Studies','Creative Arts & Sports','Religious Education','Special Needs Education','Academic Coordination'];
 const supportDepartments=['School Administration','Registry & Admissions','Finance & Accounts','Human Resources','ICT & Technology','Library Services','Guidance & Counselling','Examinations Department','Laboratory Department','Sports & Physical Education','Transport Department','Security Department','Catering & Nutrition','Health & Medical Services','Maintenance & Facilities','Cleaning & Sanitation','Boarding & Accommodation','Procurement & Stores','Support Services','Other'];
 const select=document.getElementById(departmentId);if(!select)return;
 const previous=selectedValue!==undefined?selectedValue:select.value;
 const options=teachingRoles.includes(role)?teachingDepartments:supportDepartments;
 select.replaceChildren(new Option('Select department',''));
 options.forEach(value=>select.add(new Option(value,value)));
 if(previous&&!options.includes(previous)&&selectedValue!==undefined)select.add(new Option(previous,previous));
 if(previous&&options.includes(previous))select.value=previous;
}}
filterStaffDepartment('staffAddRole','staffAddDepartment');
document.addEventListener('submit',async e=>{{const form=e.target.closest('#staff-edit-content form');if(!form)return;e.preventDefault();const content=document.getElementById('staff-edit-content'),button=form.querySelector('[type=submit]');if(button){{button.disabled=true;button.textContent='Saving…';}}try{{const r=await fetch(form.action,{{method:(form.method||'POST').toUpperCase(),body:new FormData(form),credentials:'same-origin'}});const html=await r.text();if(r.redirected||(r.ok&&html.includes('window.parent.location.reload'))){{window.location.reload();return;}}const doc=new DOMParser().parseFromString(html,'text/html');content.innerHTML=doc.body.innerHTML||html;if(!r.ok)content.insertAdjacentHTML('afterbegin','<div class="edit-load-error">Save failed (HTTP '+r.status+'). Review the message below and try again.</div>');}}catch(err){{content.insertAdjacentHTML('afterbegin','<div class="edit-load-error">Save failed: '+String(err.message)+'</div>');}}finally{{if(button&&button.isConnected){{button.disabled=false;button.textContent='Save Changes';}}}}}},true);
</script>
<style>.staff-edit-content{{max-height:calc(100% - 82px);overflow:auto;padding:0 20px 20px;background:#f7faf7}}.staff-edit-content>.page{{max-width:none;margin:0}}.staff-edit-content .card{{margin:0}}.edit-loading,.edit-load-error{{padding:18px;color:#52675a}}.edit-load-error{{color:#9b2424;background:#fff1f1;border:1px solid #f1caca;border-radius:10px}}</style>
<dialog id='find-staff-dialog' class='staff-add-dialog staff-find-dialog'><div class='staff-dialog-heading'><div><div class='staff-eyebrow'>STAFF MANAGER / DIRECTORY SEARCH</div><h2>Find staff</h2><p class='muted'>Search and narrow the staff register using the filters below.</p></div><button type='button' class='staff-dialog-close' aria-label='Close' onclick="document.getElementById('find-staff-dialog').close()">×</button></div><form method='get' class='staff-filters staff-add-form'><label>Search staff<input class='field' name='staff' value='{escape(q,quote=True)}' placeholder='Name, TSC, email or phone'></label><label>Department<select class='field' name='department'>{dept_opts}</select></label><label>Designation<select class='field' name='role'>{role_opts}</select></label><label>Employment type<select class='field' name='employment_type'>{emp_opts}</select></label><label>Status<select class='field' name='status'>{state_opts}</select></label><div class='staff-dialog-actions'><a class='btn btn-light' href='/app/staff'>Clear filters</a><button class='btn'>Apply Filters</button></div></form></dialog>
<section class='card staff-register-card'><div class='staff-register-heading'><div><h2>Staff register</h2><span class='staff-count'>{len(staff_rows)} matching staff member(s)</span></div><input id='staffRegisterSearch' class='field staff-register-search' type='search' placeholder='Search name, designation, department, email or phone' oninput='filterStaffRegister()'></div><div class='staff-register-tabs' role='tablist' aria-label='Staff categories'><button type='button' class='staff-group-tab is-active' data-staff-group='all' role='tab' aria-selected='true' onclick="setStaffGroup('all',this)">All Staff <span>{staff_group_counts['all']}</span></button><button type='button' class='staff-group-tab' data-staff-group='teaching' role='tab' aria-selected='false' onclick="setStaffGroup('teaching',this)">Teaching Staff <span>{staff_group_counts['teaching']}</span></button><button type='button' class='staff-group-tab' data-staff-group='administration' role='tab' aria-selected='false' onclick="setStaffGroup('administration',this)">Administration <span>{staff_group_counts['administration']}</span></button><button type='button' class='staff-group-tab' data-staff-group='support' role='tab' aria-selected='false' onclick="setStaffGroup('support',this)">Support Staff <span>{staff_group_counts['support']}</span></button></div><div class='staff-table-scroll'><table id='staffRegisterTable'><thead><tr><th>Name / TSC</th><th>Designation</th><th>Department</th><th>Email</th><th>Phone</th><th>Employment</th><th>Status</th><th>Actions</th></tr></thead><tbody>{rows or "<tr><td colspan='8' class='empty-state'>No staff members match these filters.</td></tr>"}</tbody></table></div></section><script>let activeStaffGroup='all';function setStaffGroup(group,button){{activeStaffGroup=group;document.querySelectorAll('.staff-group-tab').forEach(function(tab){{const active=tab===button;tab.classList.toggle('is-active',active);tab.setAttribute('aria-selected',active?'true':'false');}});filterStaffRegister();}}function filterStaffRegister(){{const q=((document.getElementById('staffRegisterSearch')||{{}}).value||'').trim().toLowerCase();document.querySelectorAll('#staffRegisterTable tbody tr').forEach(function(row){{if(!row.querySelector('td'))return;const groupMatch=activeStaffGroup==='all'||row.dataset.staffGroup===activeStaffGroup;const textMatch=!q||row.textContent.toLowerCase().includes(q);row.style.display=(groupMatch&&textMatch)?'':'none';}});}}</script><style>.staff-register-card .staff-register-heading{{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:14px}}.staff-register-card .staff-register-heading h2{{margin:0 0 4px}}.staff-register-search{{max-width:360px}}.staff-register-tabs{{display:flex;gap:8px;overflow-x:auto;padding:3px 1px 12px;margin-bottom:12px;border-bottom:1px solid #e4ece5;scrollbar-width:thin}}.staff-group-tab{{flex:0 0 auto;display:inline-flex;align-items:center;gap:9px;border:1px solid #dce8de;background:#f7faf7;color:#476352;border-radius:10px;padding:9px 13px;font-weight:750;cursor:pointer;white-space:nowrap}}.staff-group-tab span{{font-size:11px;background:#e5eee6;color:#315b40;border-radius:20px;padding:2px 7px}}.staff-group-tab:hover{{border-color:#9bbda2;background:#eff7f0}}.staff-group-tab.is-active{{background:linear-gradient(120deg,#1b6847,#2d8059);border-color:#1b6847;color:#fff;box-shadow:0 4px 12px #1b684733}}.staff-group-tab.is-active span{{background:#ffffff2b;color:#fff}}@media(max-width:600px){{.staff-register-search{{max-width:none;width:100%}}}}</style></div>{_staff_manager_styles()}"""
    return _school_page(request,"Staff List",body)




def _ensure_staff_attendance_table(cur):
    cur.execute("""CREATE TABLE IF NOT EXISTS staff_attendance(
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        school_id INTEGER NOT NULL,
        staff_id INTEGER NOT NULL,
        attendance_date TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'Present',
        remarks TEXT DEFAULT '',
        recorded_at TEXT,
        UNIQUE(school_id,staff_id,attendance_date))""")
    try:
        cur.execute("CREATE INDEX IF NOT EXISTS idx_staff_attendance_school_date ON staff_attendance(school_id,attendance_date)")
    except Exception:
        pass


@router.get("/app/staff/former", response_class=HTMLResponse)
def former_staff_page(request: Request, staff: str="", department: str="", role: str="", gender: str=""):
    sid=_school_session(request)
    if not sid:return RedirectResponse("/",303)
    if not _require_permission(request,sid,"staff.view"):return HTMLResponse("You do not have permission to view staff records.",403)
    q=str(staff or "").strip();dept=str(department or "").strip();desig=str(role or "").strip();sex=str(gender or "").strip().lower()
    con=_db();cur=con.cursor()
    departments=cur.execute("SELECT DISTINCT department FROM teachers WHERE school_id=? AND lower(coalesce(status,''))='left' AND coalesce(department,'')<>'' ORDER BY department",(sid,)).fetchall()
    sql="SELECT * FROM teachers WHERE school_id=? AND lower(coalesce(status,''))='left'";params=[sid]
    if q:
        sql+=" AND (lower(coalesce(name,'')) LIKE ? OR lower(coalesce(tsc_no,'')) LIKE ? OR lower(coalesce(phone,'')) LIKE ? OR lower(coalesce(email,'')) LIKE ?)"
        term="%"+q.casefold()+"%";params.extend([term]*4)
    if dept:sql+=" AND department=?";params.append(dept)
    if desig:sql+=" AND role=?";params.append(desig)
    if sex in ("male","female"):sql+=" AND lower(coalesce(gender,''))=?";params.append(sex)
    sql+=" ORDER BY name";rows=cur.execute(sql,params).fetchall();con.close()
    table_rows="".join(f"<tr><td><b>{escape(str(x['name'] or ''))}</b><div class='muted'>{escape(str(x['tsc_no'] or ''))}</div></td><td>{escape(str(x['role'] or ''))}</td><td>{escape(str(x['department'] or '—'))}</td><td>{escape(str(x['gender'] or '—'))}</td><td>{escape(str(x['phone'] or '—'))}</td><td>{escape(str(x['email'] or '—'))}</td><td><a class='action' href='/app/staff/edit/{int(x['id'])}'>View / Edit</a></td></tr>" for x in rows)
    dept_opts="<option value=''>All departments</option>"+"".join(f"<option value='{escape(str(d['department']),quote=True)}' {'selected' if str(d['department'])==dept else ''}>{escape(str(d['department']))}</option>" for d in departments)
    roles=["Teacher","Deputy Teacher","Head of Department","Head Teacher","Principal","Bursar","Secretary","Support Staff"]
    role_opts="<option value=''>All designations</option>"+"".join(f"<option {'selected' if x==desig else ''}>{x}</option>" for x in roles)
    gender_opts="".join(f"<option value='{v}' {'selected' if sex==v else ''}>{label}</option>" for v,label in [("","All genders"),("male","Male"),("female","Female")])
    body=f"""<div class='page students-list-page staff-manager-page'><div class='page-heading'><div><div class='staff-eyebrow'>STAFF MANAGER / EMPLOYMENT HISTORY</div><h1>Former Staff</h1><div class='muted'>A searchable archive of staff whose records are marked as Left School.</div></div><div class='no-print' style='display:flex;gap:10px;align-items:center;flex-wrap:wrap'><button class='btn btn-light' type='button' onclick="document.getElementById('formerStaffSearchDialog').showModal()">Find Former Staff</button><button class='btn' onclick='window.print()'>Print Register</button></div></div><div class='staff-kpis'><div class='staff-kpi'><span>Former staff</span><strong>{len(rows)}</strong></div></div>
<dialog id='formerStaffSearchDialog' class='former-staff-search-dialog' aria-labelledby='formerStaffSearchTitle' onclick='if(event.target===this)this.close()'><div class='former-staff-search-panel'><div class='page-heading'><div><h2 id='formerStaffSearchTitle'>Find former staff</h2><div class='muted'>Search and filter the former staff register.</div></div><button type='button' class='btn btn-light' aria-label='Close search' onclick="document.getElementById('formerStaffSearchDialog').close()">Close</button></div><form method='get' class='staff-filters'><label>Search staff<input class='field' name='staff' value='{escape(q,quote=True)}' placeholder='Name, TSC, email or phone'></label><label>Department<select class='field' name='department'>{dept_opts}</select></label><label>Former designation<select class='field' name='role'>{role_opts}</select></label><label>Gender<select class='field' name='gender'>{gender_opts}</select></label><div style='display:flex;gap:10px;flex-wrap:wrap;align-items:center'><button class='btn'>Apply Filters</button><a class='btn btn-light' href='/app/staff/former'>Clear</a></div></form></div></dialog><style>.former-staff-search-dialog{{width:min(760px,calc(100% - 28px));max-width:760px;border:0;border-radius:18px;padding:0;background:transparent;box-shadow:0 24px 70px #0f172a40}}.former-staff-search-dialog::backdrop{{background:#0f172a88;backdrop-filter:blur(3px)}}.former-staff-search-panel{{background:#fff;border:1px solid #dce8df;border-radius:18px;padding:24px;max-height:85vh;overflow:auto}}.former-staff-search-panel .page-heading{{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;margin-bottom:20px}}.former-staff-search-panel h2{{margin:0;font-size:20px}}.former-staff-search-panel .staff-filters{{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}}.former-staff-search-panel .staff-filters label{{display:grid;gap:7px;font-size:12px;font-weight:800;color:#334155}}.former-staff-search-panel .staff-filters>div{{grid-column:1/-1}}@media(max-width:560px){{.former-staff-search-panel{{padding:17px}}.former-staff-search-panel .staff-filters{{grid-template-columns:1fr}}}}</style><script>(function(){{var dialog=document.getElementById('formerStaffSearchDialog');if(!dialog)return;dialog.addEventListener('close',function(){{var opener=document.querySelector("button[onclick*=\"formerStaffSearchDialog\"]");if(opener)opener.focus()}});document.addEventListener('keydown',function(e){{if(e.key==='Escape'&&dialog.open)dialog.close()}})}})();</script>
<section class='card'><div class='page-heading'><h2>Former staff register</h2><span class='staff-count'>{len(rows)} record(s)</span></div><div class='staff-table-scroll'><table><thead><tr><th>Name / TSC</th><th>Last designation</th><th>Department</th><th>Gender</th><th>Phone</th><th>Email</th><th>Action</th></tr></thead><tbody>{table_rows or "<tr><td colspan='7' class='empty-state'>No former staff records match these filters.</td></tr>"}</tbody></table></div></section></div>{_staff_manager_styles()}"""
    return _school_page(request,"Former Staff",body)




@router.get("/app/staff/attendance", response_class=HTMLResponse)
def staff_attendance_sheet(request: Request, attendance_date: str="", department: str="", staff_id: str="", attendance_status: str=""):
    sid=_school_session(request)
    if not sid:return RedirectResponse("/",303)
    if not _require_permission(request,sid,"staff.view"):return HTMLResponse("You do not have permission to view staff attendance.",403)
    day=attendance_date if re.fullmatch(r"\d{4}-\d{2}-\d{2}",attendance_date or "") else datetime.now(ZoneInfo("Africa/Nairobi")).strftime("%Y-%m-%d")
    dept=str(department or "").strip();person=int(staff_id) if str(staff_id).isdigit() else 0;state=str(attendance_status or "").strip().title()
    con=_db();cur=con.cursor();_ensure_staff_attendance_table(cur)
    staff=cur.execute("SELECT id,name,role,department FROM teachers WHERE school_id=? AND lower(coalesce(status,'active'))<>'left' ORDER BY name",(sid,)).fetchall()
    saved=cur.execute("SELECT staff_id,status,remarks FROM staff_attendance WHERE school_id=? AND attendance_date=?",(sid,day)).fetchall()
    saved_map={int(x['staff_id']):(str(x['status'] or 'Present'),str(x['remarks'] or '')) for x in saved}
    departments=cur.execute("SELECT DISTINCT department FROM teachers WHERE school_id=? AND lower(coalesce(status,'active'))<>'left' AND coalesce(department,'')<>'' ORDER BY department",(sid,)).fetchall();con.close()
    rows="".join(f"<tr class='staff-attendance-row' data-department='{escape(str(x['department'] or ''),quote=True).lower()}' data-staff='{int(x['id'])}' data-status='{escape(saved_map.get(int(x['id']),('Present',''))[0]).lower()}'><td><b>{escape(str(x['name'] or ''))}</b><div class='muted'>{escape(str(x['role'] or ''))}</div></td><td>{escape(str(x['department'] or '—'))}</td><td><select class='field attendance-status' name='status_{int(x['id'])}'><option {'selected' if saved_map.get(int(x['id']),('Present',''))[0]=='Present' else ''}>Present</option><option {'selected' if saved_map.get(int(x['id']),('Present',''))[0]=='Absent' else ''}>Absent</option><option {'selected' if saved_map.get(int(x['id']),('Present',''))[0]=='Late' else ''}>Late</option><option {'selected' if saved_map.get(int(x['id']),('Present',''))[0]=='Excused' else ''}>Excused</option></select></td><td><input class='field' name='remarks_{int(x['id'])}' value='{escape(saved_map.get(int(x['id']),('',''))[1],quote=True)}' placeholder='Optional note'></td></tr>" for x in staff)
    dept_opts="<option value=''>All departments</option>"+"".join(f"<option value='{escape(str(d['department']),quote=True)}' {'selected' if str(d['department'])==dept else ''}>{escape(str(d['department']))}</option>" for d in departments)
    staff_opts="<option value='0'>All staff</option>"+"".join(f"<option value='{int(x['id'])}' {'selected' if int(x['id'])==person else ''}>{escape(str(x['name'] or ''))}</option>" for x in staff)
    status_opts="".join(f"<option value='{v}' {'selected' if state==v else ''}>{label}</option>" for v,label in [("","All statuses"),("Present","Present"),("Absent","Absent"),("Late","Late"),("Excused","Excused")])
    marked=sum(1 for x in staff if int(x['id']) in saved_map);present=sum(1 for x in staff if int(x['id']) in saved_map and saved_map[int(x['id'])][0]=='Present')
    body=f"""<div class='page students-list-page staff-manager-page'><div class='page-heading'><div><div class='staff-eyebrow'>STAFF MANAGER / DAILY RECORDS</div><h1>Staff Attendance Sheet</h1><div class='muted'>Record and review daily attendance for your staff and teachers.</div></div><span class='staff-count'>{day}</span></div>
<div class='staff-kpis'><div class='staff-kpi'><span>Staff on register</span><strong>{len(staff)}</strong></div><div class='staff-kpi'><span>Attendance saved</span><strong>{marked}</strong></div><div class='staff-kpi'><span>Present</span><strong>{present}</strong></div><div class='staff-kpi'><span>Awaiting record</span><strong>{max(0,len(staff)-marked)}</strong></div></div>
<section class='card no-print'><h2>Attendance filters</h2><form method='get' class='staff-filters'><label>Attendance date<input class='field' type='date' name='attendance_date' value='{day}' required></label><label>Department<select class='field' name='department'>{dept_opts}</select></label><label>Staff member<select class='field' name='staff_id'>{staff_opts}</select></label><label>Current status<select class='field' name='attendance_status'>{status_opts}</select></label><button class='btn'>Load Attendance</button><a class='btn btn-light' href='/app/staff/attendance'>Today</a></form></section>
<section class='card'><div class='page-heading'><h2>Daily attendance register</h2><span class='staff-count'>Save records for the selected date</span></div><form method='post' action='/app/staff/attendance/save'><input type='hidden' name='attendance_date' value='{day}'><div class='staff-table-scroll'><table><thead><tr><th>Staff member</th><th>Department</th><th>Attendance status</th><th>Remarks</th></tr></thead><tbody>{rows or "<tr><td colspan='4' class='empty-state'>No current staff records available.</td></tr>"}</tbody></table></div>{'<button class="btn no-print" style="margin-top:16px">Save Attendance</button>' if staff else ''}</form></section></div>
<script>(function(){{const dept={json.dumps(dept.lower())},person={person},status={json.dumps(state.lower())};document.querySelectorAll('.staff-attendance-row').forEach(row=>{{const select=row.querySelector('.attendance-status');const current=(select&&select.value||row.dataset.status||'').toLowerCase();row.hidden=!!((dept&&row.dataset.department!==dept)||(person&&Number(row.dataset.staff)!==person)||(status&&current!==status));}});}})();</script>{_staff_manager_styles()}"""
    return _school_page(request,"Staff Attendance Sheet",body)




@router.post("/app/staff/attendance/save")
async def staff_attendance_save(request: Request, attendance_date: str=Form(...)):
    sid=_school_session(request)
    if not sid:return RedirectResponse("/",303)
    if not _require_permission(request,sid,"staff.edit"):
        return HTMLResponse("You do not have permission to edit staff attendance.",403)
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}",attendance_date or ""):
        return HTMLResponse("Choose a valid attendance date.",400)
    form=await request.form();con=_db();cur=con.cursor();_ensure_staff_attendance_table(cur)
    staff=cur.execute("SELECT id FROM teachers WHERE school_id=? AND lower(coalesce(status,'active'))<>'left'",(sid,)).fetchall()
    now=datetime.now(ZoneInfo("Africa/Nairobi")).isoformat(timespec="seconds")
    for person in staff:
        staff_id=int(person["id"])
        status=str(form.get(f"status_{staff_id}") or "Present").strip().title()
        if status not in ("Present","Absent","Late","Excused"):status="Present"
        remarks=str(form.get(f"remarks_{staff_id}") or "").strip()[:500]
        old=cur.execute("SELECT id FROM staff_attendance WHERE school_id=? AND staff_id=? AND attendance_date=?",(sid,staff_id,attendance_date)).fetchone()
        if old:
            cur.execute("UPDATE staff_attendance SET status=?,remarks=?,recorded_at=? WHERE id=? AND school_id=?",(status,remarks,now,old["id"],sid))
        else:
            cur.execute("INSERT INTO staff_attendance(school_id,staff_id,attendance_date,status,remarks,recorded_at) VALUES(?,?,?,?,?,?)",(sid,staff_id,attendance_date,status,remarks,now))
    _audit(cur,sid,request,"STAFF_ATTENDANCE_SAVE",f"Saved staff attendance for {attendance_date}")
    con.commit();con.close()
    return RedirectResponse(f"/app/staff/attendance?attendance_date={quote(attendance_date,safe='')}",303)


@router.get("/app/staff/attendance-report", response_class=HTMLResponse)
def staff_attendance_report(request: Request, start_date: str="", end_date: str="", department: str="", staff_id: str="", attendance_status: str=""):
    sid=_school_session(request)
    if not sid:return RedirectResponse("/",303)
    if not _require_permission(request,sid,"staff.view"):return HTMLResponse("You do not have permission to view staff attendance reports.",403)
    today=datetime.now(ZoneInfo("Africa/Nairobi")).strftime("%Y-%m-%d")
    end=end_date if re.fullmatch(r"\d{4}-\d{2}-\d{2}",end_date or "") else today
    start=start_date if re.fullmatch(r"\d{4}-\d{2}-\d{2}",start_date or "") else end[:8]+"01"
    dept=str(department or "").strip();person=int(staff_id) if str(staff_id).isdigit() else 0;state=str(attendance_status or "").strip().title()
    con=_db();cur=con.cursor();_ensure_staff_attendance_table(cur)
    departments=cur.execute("SELECT DISTINCT department FROM teachers WHERE school_id=? AND coalesce(department,'')<>'' ORDER BY department",(sid,)).fetchall()
    people=cur.execute("SELECT id,name FROM teachers WHERE school_id=? ORDER BY name",(sid,)).fetchall()
    sql="""SELECT t.id staff_id,t.name,t.role,t.department,COUNT(a.id) days,
      SUM(CASE WHEN a.status='Present' THEN 1 ELSE 0 END) present,
      SUM(CASE WHEN a.status='Absent' THEN 1 ELSE 0 END) absent,
      SUM(CASE WHEN a.status='Late' THEN 1 ELSE 0 END) late,
      SUM(CASE WHEN a.status='Excused' THEN 1 ELSE 0 END) excused
      FROM teachers t LEFT JOIN staff_attendance a ON a.staff_id=t.id AND a.school_id=t.school_id AND a.attendance_date BETWEEN ? AND ?"""
    params=[start,end]
    if state in ("Present","Absent","Late","Excused"):sql+=" AND a.status=?";params.append(state)
    sql+=" WHERE t.school_id=?";params.append(sid)
    if dept:sql+=" AND t.department=?";params.append(dept)
    if person:sql+=" AND t.id=?";params.append(person)
    sql+=" GROUP BY t.id,t.name,t.role,t.department ORDER BY t.name"
    rows=cur.execute(sql,params).fetchall();con.close()
    cells="".join(f"<tr><td><b>{escape(str(x['name'] or ''))}</b><div class='muted'>{escape(str(x['department'] or '—'))}</div></td><td>{escape(str(x['role'] or ''))}</td><td>{int(x['days'] or 0)}</td><td>{int(x['present'] or 0)}</td><td>{int(x['absent'] or 0)}</td><td>{int(x['late'] or 0)}</td><td>{int(x['excused'] or 0)}</td></tr>" for x in rows)
    totals={k:sum(int(x[k] or 0) for x in rows) for k in ("days","present","absent","late","excused")}
    dept_opts="<option value=''>All departments</option>"+"".join(f"<option value='{escape(str(d['department']),quote=True)}' {'selected' if str(d['department'])==dept else ''}>{escape(str(d['department']))}</option>" for d in departments)
    people_opts="<option value='0'>All staff</option>"+"".join(f"<option value='{int(x['id'])}' {'selected' if int(x['id'])==person else ''}>{escape(str(x['name'] or ''))}</option>" for x in people)
    status_opts="".join(f"<option value='{v}' {'selected' if state==v else ''}>{label}</option>" for v,label in [("","All statuses"),("Present","Present"),("Absent","Absent"),("Late","Late"),("Excused","Excused")])
    body=f"""<div class='page students-list-page staff-manager-page'><div class='page-heading'><div><div class='staff-eyebrow'>STAFF MANAGER / ATTENDANCE INSIGHTS</div><h1>Staff Attendance Report</h1><div class='muted'>Review attendance patterns and recorded days across a selected period.</div></div><button class='btn no-print' onclick='window.print()'>Print Report</button></div>
<section class='card no-print'><h2>Report filters</h2><form method='get' class='staff-filters'><label>From date<input class='field' type='date' name='start_date' value='{start}'></label><label>To date<input class='field' type='date' name='end_date' value='{end}'></label><label>Department<select class='field' name='department'>{dept_opts}</select></label><label>Staff member<select class='field' name='staff_id'>{people_opts}</select></label><label>Attendance status<select class='field' name='attendance_status'>{status_opts}</select></label><button class='btn'>Generate Report</button><a class='btn btn-light' href='/app/staff/attendance-report'>Clear</a></form></section>
<div class='staff-count' style='margin:8px 2px 12px'>Reporting period: <b>{start}</b> to <b>{end}</b></div><div class='staff-kpis'><div class='staff-kpi'><span>Staff shown</span><strong>{len(rows)}</strong></div><div class='staff-kpi'><span>Attendance records</span><strong>{totals['days']}</strong></div><div class='staff-kpi'><span>Present</span><strong>{totals['present']}</strong></div><div class='staff-kpi'><span>Absent</span><strong>{totals['absent']}</strong></div></div>
<section class='card'><div class='page-heading'><h2>Attendance breakdown</h2><span class='staff-count'>{len(rows)} staff member(s)</span></div><div class='staff-table-scroll'><table><thead><tr><th>Staff member</th><th>Designation</th><th>Recorded days</th><th>Present</th><th>Absent</th><th>Late</th><th>Excused</th></tr></thead><tbody>{cells or "<tr><td colspan='7' class='empty-state'>No staff attendance records found for this period and filter selection.</td></tr>"}</tbody></table></div><div class='staff-count' style='margin-top:12px'>Totals — {totals['present']} present · {totals['absent']} absent · {totals['late']} late · {totals['excused']} excused</div></section></div>{_staff_manager_styles()}"""
    return _school_page(request,"Staff Attendance Report",body)




# Compatibility endpoint for older FastAPI Cloud pages that submit to /app/staff.
# Keep the canonical form action at /app/staff/add; both paths use the same save handler.
@router.post("/app/staff")
@router.post("/app/staff/add")
def staff_add(request: Request,name:str=Form(...),email:str=Form(""),phone:str=Form(""),tsc_no:str=Form(""),id_no:str=Form(""),role:str=Form("Teacher"),gender:str=Form(""),employment_type:str=Form("Permanent"),status:str=Form("active"),department:str=Form("")):
    sid=_school_session(request)
    if not sid:
        return RedirectResponse("/",303)
    if not _require_permission(request, sid, "staff.create"):
        return HTMLResponse("You do not have permission to add staff.", 403)

    allowed_status=("active","inactive","on_leave","left")
    new_status=status.strip().lower() if status.strip().lower() in allowed_status else "active"
    email_v=email.strip()
    tsc_v=tsc_no.strip()
    id_v=id_no.strip()
    con=None
    try:
        con=_db()
        cur=con.cursor()

        # Repair older teachers tables on the actual connection used by this
        # save request. Startup migrations can run before a hosted database is
        # reachable, so do not assume optional columns already exist here.
        teacher_columns={
            "school_id":"INTEGER", "name":"TEXT", "email":"TEXT", "phone":"TEXT",
            "tsc_no":"TEXT", "gender":"TEXT", "id_no":"TEXT", "role":"TEXT",
            "employment_type":"TEXT", "status":"TEXT", "department":"TEXT"
        }
        cur.execute("SELECT * FROM teachers LIMIT 0")
        existing={str(col.name if hasattr(col,"name") else col[0]).lower() for col in (cur.description or [])}
        for column,definition in teacher_columns.items():
            if column in existing:
                continue
            try:
                cur.execute(f"ALTER TABLE teachers ADD COLUMN IF NOT EXISTS {column} {definition}")
            except Exception:
                try:
                    con.rollback()
                except Exception:
                    pass
                cur.execute(f"ALTER TABLE teachers ADD COLUMN {column} {definition}")
            existing.add(column)
        con.commit()

        if email_v and cur.execute("SELECT id FROM teachers WHERE school_id=? AND lower(email)=lower(?)",(sid,email_v)).fetchone():
            con.close()
            return HTMLResponse("A staff member with that email already exists. <a href='/app/staff'>Back</a>",400)
        if tsc_v and cur.execute("SELECT id FROM teachers WHERE school_id=? AND lower(tsc_no)=lower(?)",(sid,tsc_v)).fetchone():
            con.close()
            return HTMLResponse("That TSC number already exists. <a href='/app/staff'>Back</a>",400)
        if id_v and cur.execute("SELECT id FROM teachers WHERE school_id=? AND lower(id_no)=lower(?)",(sid,id_v)).fetchone():
            con.close()
            return HTMLResponse("That ID number already exists. <a href='/app/staff'>Back</a>",400)

        cur.execute(
            "INSERT INTO teachers(school_id,name,email,phone,tsc_no,gender,id_no,role,employment_type,status,department) VALUES(?,?,?,?,?,?,?,?,?,?,?)",
            (sid,name.strip(),email_v,phone.strip(),tsc_v,gender.strip(),id_v,role.strip(),employment_type.strip(),new_status,department.strip())
        )
        _audit(cur,sid,request,"STAFF_CREATE",f"Created staff member {name.strip()}")
        con.commit()
    except Exception as exc:
        import traceback
        try:
            if con is not None:
                con.rollback()
        except Exception:
            pass
        print(f"MABALE_ICT STAFF SAVE ERROR school_id={sid} error={exc!r}",flush=True)
        traceback.print_exc()
        return HTMLResponse(
            "<h2>Staff was not saved</h2><p>The database rejected this save. "
            "Please retry once after the latest deployment.</p><p>Reference: STAFF-SAVE-01</p>"
            "<a href='/app/staff'>Back to Staff & Teachers</a>",500
        )
    finally:
        if con is not None:
            try:
                con.close()
            except Exception:
                pass
    return RedirectResponse("/app/staff",303)

@router.get("/app/staff/edit/{teacher_id}",response_class=HTMLResponse)
def staff_edit_page(request: Request,teacher_id:int,modal:int=0):
    sid=_school_session(request)
    if not sid:return RedirectResponse("/")
    tab_id=str(request.query_params.get("ds_tab") or request.scope.get("davischool_tab_id") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_-]{16,64}",tab_id):tab_id=""
    tab_q=("?ds_tab="+quote(tab_id,safe="")) if tab_id else ""
    if not _require_permission(request, sid, "staff.edit"):
        return HTMLResponse("You do not have permission to edit staff records.", 403)
    con=_db();cur=con.cursor(); t=cur.execute("SELECT * FROM teachers WHERE id=? AND school_id=?",(teacher_id,sid)).fetchone(); con.close()
    if not t:return HTMLResponse("Staff member not found.",404)
    def val(key,default=""):
        try:return str(t[key] if t[key] is not None else default)
        except Exception:return default
