@router.post("/app/academics/subject-allocation")
async def save_student_subject_allocation(request: Request):
    sid=_school_session(request)
    if not sid:return RedirectResponse("/",303)
    if str(request.session.get("role","")) not in ("school_admin","registrar"):
        return HTMLResponse("Subject Allocation is available to School Admin and Registrar only.",403)
    if not _require_permission(request,sid,"marks.edit"):
        return HTMLResponse("You do not have permission to manage student subject allocations.",403)
    form=await request.form()
    year=str(form.get("academic_year") or "").strip()
    examination_id=str(form.get("examination_id") or "").strip()
    term=str(form.get("term") or "").strip()
    try:
        cid=int(form.get("class_id") or 0);subid=int(form.get("subject_id") or 0)
    except Exception:
        return HTMLResponse("Invalid class or subject selection.",400)
    if not year.isdigit() or not cid or not subid or not examination_id.isdigit() or not term:
        return HTMLResponse("Select an examination, term, class, and subject.",400)
    con=_db()
    try:
        cur=con.cursor()
        _ensure_student_subject_allocations_table(cur)
        _ensure_student_promotion_cohort_tables(cur)
        selected_exam=cur.execute("SELECT year,term FROM exams WHERE school_id=? AND id=?",(sid,int(examination_id))).fetchone()
        valid=cur.execute("SELECT 1 FROM classes WHERE school_id=? AND id=?",(sid,cid)).fetchone() and cur.execute("SELECT 1 FROM subjects WHERE school_id=? AND id=?",(sid,subid)).fetchone()
        if not valid or not selected_exam or str(selected_exam["year"] or "")!=year or str(selected_exam["term"] or "")!=term:
            con.rollback();return HTMLResponse("The selected class or subject does not belong to this school.",403)
        roster=cur.execute("""SELECT s.id FROM students s WHERE s.school_id=? AND (s.class_id=? OR EXISTS(
            SELECT 1 FROM student_promotion_cohort_members cohort_current
            WHERE cohort_current.school_id=s.school_id AND cohort_current.cycle_year=CAST(? AS INTEGER)
              AND cohort_current.class_id=? AND cohort_current.student_id=s.id))
            AND lower(coalesce(s.status,'active'))='active'
            AND NOT EXISTS(SELECT 1 FROM student_graduations g WHERE g.school_id=s.school_id AND g.student_id=s.id)
            -- Current class membership is authoritative for the selected year;
            -- the OR above also preserves the historical promotion cohort.
""",(sid,cid,year,cid)).fetchall()
        eligible={int(x["id"]) for x in roster}
        requested={int(x) for x in form.getlist("student_ids") if str(x).isdigit()}
        if not requested.issubset(eligible):
            con.rollback();return HTMLResponse("One or more selected learners do not belong to this academic-year class cohort.",403)
        cur.execute("DELETE FROM student_subject_allocations WHERE school_id=? AND academic_year=? AND class_id=? AND subject_id=?",(sid,year,cid,subid))
        now=datetime.now(ZoneInfo("Africa/Nairobi")).strftime("%Y-%m-%d %H:%M:%S")
        cur.execute("""INSERT INTO student_subject_allocation_registers
            (school_id,academic_year,class_id,subject_id,configured_at)
            SELECT ?,?,?,?,? WHERE NOT EXISTS (
                SELECT 1 FROM student_subject_allocation_registers
                WHERE school_id=? AND academic_year=? AND class_id=? AND subject_id=?
            )""",(sid,year,cid,subid,now,sid,year,cid,subid))
        if requested:
            cur.executemany("""INSERT INTO student_subject_allocations
                (school_id,academic_year,class_id,subject_id,student_id,allocated_at)
                VALUES(?,?,?,?,?,?)""",[(sid,year,cid,subid,x,now) for x in sorted(requested)])
        con.commit()
    except Exception as exc:
        try:con.rollback()
        except Exception:pass
        print("MABALE_ICT STUDENT SUBJECT ALLOCATION SAVE ERROR:",repr(exc),flush=True)
        return HTMLResponse("Subject allocations could not be saved. Please try again.",500)
    finally:
        con.close()
    return RedirectResponse("/app/academics/subject-allocation?academic_year=%s&examination_id=%s&term=%s&subject_id=%s&class_name=%s&stream=%s&load=1&saved=1"%(quote(year,safe=""),quote(examination_id,safe=""),quote(term,safe=""),subid,quote(str(form.get("class_name") or ""),safe=""),quote(str(form.get("stream") or ""),safe="")),303)


@router.get("/app/academics/submission-tracker", response_class=HTMLResponse)
@router.get("/app/academics", response_class=HTMLResponse)
def academics_page(request: Request, exam_id: str = "", class_id: str = "", subject_id: str = "", term: str = "", year: str = ""):
    tracker_page = request.url.path == "/app/academics/submission-tracker"
    sid = _school_session(request)
    if not sid: return RedirectResponse("/")
    if not _require_permission(request, sid, "marks.view"):
        return HTMLResponse("You do not have permission to view academic records.", 403)
    con = _db(); cur = con.cursor()
    role = str(request.session.get("role",""))
    allocations = []
    if role == "teacher":
        teacher_id = int(request.session.get("teacher_id") or 0)
        if teacher_id:
            allocations = cur.execute("""SELECT DISTINCT class_id,subject_id
                FROM teacher_allocations
                WHERE school_id=? AND teacher_id=?
                ORDER BY class_id,subject_id""",(sid,teacher_id)).fetchall()
            class_ids = sorted({int(a["class_id"]) for a in allocations if a["class_id"] is not None})
            subject_ids = sorted({int(a["subject_id"]) for a in allocations if a["subject_id"] is not None})
            if class_ids:
                ph = ",".join("?" for _ in class_ids)
                classes = cur.execute("SELECT * FROM classes WHERE school_id=? AND id IN ("+ph+") ORDER BY name,stream",[sid]+class_ids).fetchall()
            else:
                classes = []
            if subject_ids:
                ph = ",".join("?" for _ in subject_ids)
                subjects = cur.execute("SELECT * FROM subjects WHERE school_id=? AND id IN ("+ph+") ORDER BY name",[sid]+subject_ids).fetchall()
            else:
                subjects = []
        else:
            classes = []
            subjects = []
    else:
        classes = cur.execute("SELECT * FROM classes WHERE school_id=? ORDER BY name,stream",(sid,)).fetchall()
        subjects = cur.execute("SELECT * FROM subjects WHERE school_id=? ORDER BY name",(sid,)).fetchall()
    terms = cur.execute("SELECT * FROM terms WHERE school_id=? ORDER BY id DESC",(sid,)).fetchall()
    exams = cur.execute("SELECT * FROM exams WHERE school_id=? ORDER BY id DESC",(sid,)).fetchall()
    stat = cur.execute("SELECT COUNT(*) entries,COALESCE(AVG(marks),0) avg_mark FROM marks WHERE school_id=?",(sid,)).fetchone()
    eid = int(exam_id) if exam_id.isdigit() else 0
    cid = int(class_id) if class_id.isdigit() else 0
    subid = int(subject_id) if subject_id.isdigit() else 0
    params=[sid]; query="SELECT COUNT(*) entries,COALESCE(AVG(marks),0) avg_mark,COALESCE(MAX(marks),0) high,COALESCE(MIN(marks),0) low FROM marks WHERE school_id=?"
    if eid: query+=" AND exam_id=?"; params.append(eid)
    if cid: query+=" AND class_id=?"; params.append(cid)
    if subid: query+=" AND subject_id=?"; params.append(subid)
    if term: query+=" AND term=?"; params.append(term.strip())
    if year: query+=" AND year=?"; params.append(year.strip())
    selected=cur.execute(query,params).fetchone(); con.close()
    if tracker_page and role not in ("school_admin","registrar"):
        return RedirectResponse("/app/academics", status_code=303)
    eopts="".join("<option value='%s' %s>%s</option>"%(e["id"],"selected" if int(e["id"])==eid else "",escape(str(e["name"]))) for e in exams)
    # For teachers these lists are already restricted above to their allocation IDs.
    # Build the dropdowns from those restricted rows only; never render the school's
    # full class/subject catalogue into a teacher's Marks Entry form.
    if role=="teacher":
        allowed_class_ids={int(a["class_id"]) for a in allocations if a["class_id"] is not None}
        allowed_subject_ids={int(a["subject_id"]) for a in allocations if a["subject_id"] is not None}
        teacher_classes=[x for x in classes if int(x["id"]) in allowed_class_ids]
        teacher_subjects=[x for x in subjects if int(x["id"]) in allowed_subject_ids]
        copts="".join("<option value='%s' %s>%s %s</option>"%(c["id"],"selected" if int(c["id"])==cid else "",escape(str(c["name"])),escape(str(c["stream"] or ""))) for c in teacher_classes)
        sopts="".join("<option value='%s' %s>%s</option>"%(s["id"],"selected" if int(s["id"])==subid else "",escape(str(s["name"]))) for s in teacher_subjects)
    else:
        copts="".join("<option value='%s' %s>%s %s</option>"%(c["id"],"selected" if int(c["id"])==cid else "",escape(str(c["name"])),escape(str(c["stream"] or ""))) for c in classes)
        sopts="".join("<option value='%s' %s>%s</option>"%(s["id"],"selected" if int(s["id"])==subid else "",escape(str(s["name"]))) for s in subjects)
    topts="".join("<option %s>%s</option>"%("selected" if x==term else "",x) for x in TERM_OPTIONS)
    yopts="".join("<option value='%s' %s>%s</option>"%(y,"selected" if y==year else "",y) for y in YEAR_OPTIONS)
    actions=[("/app/academics/subject-allocation",_modern_icon("allocation"),"Subject Allocation","Choose which learners sit each subject by academic year"),("/app/academics/marks",_modern_icon("marks"),"Marks Entry","Enter and update learner marks"),("/app/academics/marksheets",_modern_icon("report"),"Class Marksheets","View class marks"),("/app/academics/analysis",_modern_icon("analysis"),"Academic Analysis","View overall academic analysis"),("/app/academics/grading",_modern_icon("grading"),"Grade & Points","Set subject grading rules"),("/app/academics/allocations",_modern_icon("allocation"),"Teacher Allocation","Assign teachers"),("/app/exams",_modern_icon("exam"),"Examinations","Manage examinations"),("/app/report-cards",_modern_icon("report"),"Report Cards","Generate reports"),("/app/subjects",_modern_icon("subject"),"Subjects","Manage subjects"),("/app/classes",_modern_icon("school"),"Classes & Streams","Manage classes")] 
    if role in ("school_admin","registrar"):
        actions.append(("/app/academics/marks-corrections",_modern_icon("correction"),"Marks Corrections","Review teacher correction requests"))
        actions.append(("/app/students/promotion",_modern_icon("students"),"Promotion","Promote learners and manage class transfers"))
        # Keep the tracker as the final tile; mobile CSS gives it a full two-column row.
        actions.append(("/app/academics/submission-tracker",_modern_icon("audit"),"Examination Submission Tracker","Track subject submissions by examination"))
    # Preserve the current isolated browser-tab session when opening an Academic Manager tile.
    # The explicit query parameter prevents the tile navigation from falling back to the
    # generic login session even if the browser-side tab script has not run yet.
    current_ds_tab=str(request.query_params.get("ds_tab") or request.scope.get("davischool_tab_id") or "").strip()
    if not re.fullmatch(r"[A-Za-z0-9_-]{16,64}", current_ds_tab):
        current_ds_tab=""
    academic_groups=[
        ("marks-assessments","Marks & Assessments",["Marks Entry","Class Marksheets","Marks Corrections","Examination Submission Tracker"]),
        ("analysis-reports","Analysis & Reports",["Academic Analysis","Report Cards"]),
        ("academic-setup","Academic Setup",["Grade & Points","Teacher Allocation","Examinations","Subjects","Classes & Streams"]),
        ("learner-subjects","Learner Subject Choices",["Subject Allocation"]),
        ("learner-progression","Learner Progression",["Promotion"]),
    ]
    action_by_title={x[2]:x for x in actions}
    visible_groups=[(gid,label,[action_by_title[name] for name in names if name in action_by_title]) for gid,label,names in academic_groups]
    visible_groups=[g for g in visible_groups if g[2]]
    nav_html="".join("<button class='academic-hub-navlink' type='button' data-academic-target='academic-group-%s' aria-controls='academic-group-%s' aria-expanded='%s'>%s<span aria-hidden='true'>›</span></button>"%(gid,gid,"true" if index==0 else "false",escape(label)) for index,(gid,label,_) in enumerate(visible_groups))
    group_html=[]
    for index,(gid,label,group_actions) in enumerate(visible_groups):
        rows="".join("<a class='academic-manager-tile academic-manager-row' data-academic-prefetch='1' href='%s%s'><span class='academic-manager-row-icon'>%s</span><span class='academic-manager-row-copy'><strong>%s</strong><small>%s</small></span><span class='academic-manager-row-arrow' aria-hidden='true'>›</span></a>"%(x[0],("?ds_tab="+quote(current_ds_tab,safe="")) if current_ds_tab else "",x[1],escape(x[2]),escape(x[3])) for x in group_actions)
        group_html.append("<section class='academic-hub-group' id='academic-group-%s' %s><h2>%s</h2><div class='academic-hub-list'>%s</div></section>"%(gid,"" if index==0 else "hidden",escape(label),rows))
    action_html="<div class='academic-hub'><nav class='academic-hub-nav' aria-label='Academic management sections'>%s</nav><div class='academic-hub-content'>%s</div></div><style>.academic-hub{display:grid;grid-template-columns:210px minmax(0,1fr);gap:22px;align-items:start;margin-top:24px}.academic-hub-nav{position:sticky;top:88px;display:grid;gap:5px;padding:9px;background:#E8F5E9;border:1px solid #A5D6A7;border-radius:13px}.academic-hub-navlink{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:11px 12px;border:0;background:transparent;border-radius:9px;color:#365844;font:inherit;font-size:13px;font-weight:750;text-align:left;cursor:pointer;transition:background .15s,color .15s}.academic-hub-navlink[aria-expanded='true']{background:#176B3A;color:#fff}.academic-hub-group[hidden]{display:none!important}.academic-hub-navlink span{font-size:20px;color:#78927e}.academic-hub-navlink:hover,.academic-hub-navlink:focus-visible{background:#176B3A;color:#fff;outline:none}.academic-hub-content{display:grid;gap:18px;min-width:0}.academic-hub-group{scroll-margin-top:95px;background:#fff;border:1px solid #e0e9e1;border-radius:14px;padding:16px 18px;min-width:0}.academic-hub-group h2{margin:0 0 9px;color:#24543a;font-size:14px;letter-spacing:.045em;text-transform:uppercase}.academic-hub-list{display:grid}.academic-manager-row{display:flex;align-items:center;gap:13px;padding:12px 8px;border:0;border-bottom:1px solid #edf2ed;border-radius:0;background:transparent;color:#203e2b;text-decoration:none;min-width:0;transition:background .15s,color .15s}.academic-manager-row:last-child{border-bottom:0}.academic-manager-row:hover,.academic-manager-row:focus-visible{background:#176B3A;color:#fff;box-shadow:none;transform:none;outline:none}.academic-manager-row-icon{display:grid;place-items:center;flex:0 0 38px;width:38px;height:38px;margin:0;border-radius:10px;background:#C8E6C9;color:#286341;font-size:19px}.academic-manager-row-copy{display:grid;gap:2px;min-width:0}.academic-manager-row-copy strong{font-size:13px;font-weight:800}.academic-manager-row-copy small{font-size:11px;color:#718176;font-weight:500}.academic-manager-row-arrow{margin-left:auto;font-size:23px;color:#8ba092}.academic-manager-row:hover .academic-manager-row-arrow{color:#fff}.academic-manager-row:hover .academic-manager-row-copy strong,.academic-manager-row:hover .academic-manager-row-copy small{color:#fff}@media(max-width:760px){.academic-hub{grid-template-columns:minmax(0,1fr);gap:12px}.academic-hub-nav{position:static;display:flex;overflow-x:auto;gap:5px;padding:6px;scrollbar-width:thin;-webkit-overflow-scrolling:touch}.academic-hub-navlink{flex:0 0 auto;white-space:nowrap;padding:9px 11px;background:#fff;border:1px solid #e1eae2}.academic-hub-navlink span{display:none}.academic-hub-group{padding:13px}.academic-manager-row{gap:10px;padding:11px 5px}.academic-manager-row-icon{flex-basis:34px;width:34px;height:34px}}@media(prefers-reduced-motion:reduce){.academic-hub-navlink,.academic-manager-row{transition:none}}</style><script>(function(){var hub=document.currentScript.previousElementSibling.previousElementSibling;if(!hub||!hub.classList||!hub.classList.contains('academic-hub')){hub=document.querySelector('.academic-hub');}if(!hub)return;hub.querySelectorAll('.academic-hub-navlink').forEach(function(button){button.addEventListener('click',function(){var targetId=button.getAttribute('data-academic-target');hub.querySelectorAll('.academic-hub-group').forEach(function(section){section.hidden=section.id!==targetId;});hub.querySelectorAll('.academic-hub-navlink').forEach(function(item){item.setAttribute('aria-expanded',item===button?'true':'false');});});});})();</script>"%(nav_html,"".join(group_html))
    if tracker_page:
        body="<div class='page'><h1>Examination Submission Tracker</h1><div class='muted'>Track subject submissions for each examination, including historical class/stream allocations.</div>"
    else:
        body="<div class='page'><h1>Academic Manager</h1><div class='muted'>Select options below to work with marks, assessments, analysis and reports.</div><div class='grid'><div class='card'><div class='label'>Subjects</div><div class='kpi'>%d</div></div><div class='card'><div class='label'>Exams</div><div class='kpi'>%d</div></div></div>"%(len(subjects),len(exams))
        body+="<div class='section academic-manager-section'>"+action_html+"</div>"
    # Admin-only tracker page: keep its existing filters, table, and status calculations.
    if role in ("school_admin","registrar") and tracker_page:
        tracker_raw=str(request.query_params.get("tracker_exam_id") or "").strip()
        tracker_exam_id=int(tracker_raw) if tracker_raw.isdigit() else (int(exams[0]["id"]) if exams else 0)
        tracker_exam=next((e for e in exams if int(e["id"])==tracker_exam_id),None)
        tracker_class_raw=str(request.query_params.get("tracker_class_id") or "").strip()
        tracker_class_id_filter=int(tracker_class_raw) if tracker_class_raw.isdigit() else 0
        tracker_status_filter=str(request.query_params.get("tracker_status") or "").strip().lower()
        if tracker_status_filter not in ("pending","progress","complete"):
            tracker_status_filter=""
        tracker_load=str(request.query_params.get("tracker_load") or "")=="1"
        tracker_tab=str(request.query_params.get("ds_tab") or "").strip()
        tracker_hidden=("<input type='hidden' name='ds_tab' value='%s'>" % escape(tracker_tab,quote=True)) if re.fullmatch(r"[A-Za-z0-9_-]{16,64}",tracker_tab) else ""
        tracker_options="".join("<option value='%s' %s>%s — %s %s</option>"%(e["id"],"selected" if int(e["id"])==tracker_exam_id else "",escape(str(e["name"] or "")),escape(str(e["term"] or "")),escape(str(e["year"] or ""))) for e in exams)
        # Use the examination's saved participation scope when available, so
        # participating classes remain selectable even before any marks are entered.
        # For legacy exams without a saved scope, fall back to historical class IDs
        # on saved marks; these IDs preserve the class that actually sat the exam.
        tracker_filter_participating_ids=set()
        if tracker_exam:
            filter_con=_db()
            try:
                participation_ids=_exam_participating_class_ids(filter_con.cursor(),sid,tracker_exam_id)
                if participation_ids is not None:
                    tracker_filter_participating_ids={int(x) for x in participation_ids}
                else:
                    filter_rows=filter_con.execute("""SELECT DISTINCT class_id FROM marks
                        WHERE school_id=? AND exam_id=? AND class_id IS NOT NULL""",(sid,tracker_exam_id)).fetchall()
                    tracker_filter_participating_ids={int(row["class_id"]) for row in filter_rows}
            finally:
                filter_con.close()
        tracker_filter_classes=[c for c in classes if not tracker_exam or int(c["id"]) in tracker_filter_participating_ids]
        if tracker_class_id_filter and tracker_class_id_filter not in tracker_filter_participating_ids:
            tracker_class_id_filter=0
        tracker_class_options="<option value=''>All participating classes / streams</option>"+"".join("<option value='%s' %s>%s %s</option>"%(c["id"],"selected" if int(c["id"])==tracker_class_id_filter else "",escape(str(c["name"] or "Class")),escape(str(c["stream"] or ""))) for c in tracker_filter_classes)
        tracker_status_options="".join("<option value='%s' %s>%s</option>"%(v,"selected" if tracker_status_filter==v else "",label) for v,label in (("","All statuses"),("pending","Pending"),("progress","In progress"),("complete","Completed")))
        tracker_rows=[]
        tracker_error=""
        if tracker_exam:
            tracker_con=_db()
            tracker_cur=tracker_con.cursor()
            try:
                participating_ids=_exam_participating_class_ids(tracker_cur,sid,tracker_exam_id)
                exam_year_raw=str(tracker_exam["year"] or "").strip()
                exam_year=int(exam_year_raw) if exam_year_raw.isdigit() else 0
                # For exams with an explicit saved participation scope, that scope
                # identifies every class that took part, including classes still
                # pending their first submission. For legacy exams without a scope,
                # derive participation from the historical class IDs on saved marks.
                marked_class_rows=tracker_cur.execute("""SELECT DISTINCT class_id FROM marks
                    WHERE school_id=? AND exam_id=? AND class_id IS NOT NULL""",(sid,tracker_exam_id)).fetchall()
                marked_class_ids={int(row["class_id"]) for row in marked_class_rows}
                if participating_ids is None:
                    participating_ids=marked_class_ids
                tracker_con.commit()
                participating_classes=[c for c in classes if participating_ids is not None and int(c["id"]) in participating_ids]
                assignment_rows=tracker_cur.execute("""SELECT DISTINCT a.class_id,a.subject_id,a.teacher_id,
                    COALESCE(NULLIF(trim(t.name),''),'Unassigned teacher') AS teacher_name
                    FROM teacher_allocations a
                    LEFT JOIN teachers t ON t.id=a.teacher_id AND t.school_id=a.school_id
                    WHERE a.school_id=? ORDER BY a.class_id,a.subject_id,teacher_name""",(sid,)).fetchall()
                subjects_by_class={}
                teachers_by_class_subject={}
                for allocation in assignment_rows:
                    if allocation["class_id"] is not None and allocation["subject_id"] is not None:
                        allocation_class_id=int(allocation["class_id"])
                        allocation_subject_id=int(allocation["subject_id"])
                        subjects_by_class.setdefault(allocation_class_id,set()).add(allocation_subject_id)
                        teacher_name=str(allocation["teacher_name"] or "Unassigned teacher").strip()
                        teacher_names=teachers_by_class_subject.setdefault((allocation_class_id,allocation_subject_id),[])
                        if teacher_name and teacher_name not in teacher_names:
                            teacher_names.append(teacher_name)
                # A class row can be reused after its cohort is promoted. Current
                # teacher_allocations then belong to the next cohort (or may be
                # stale rows awaiting fresh allocations), not to the old cohort
                # that sat this examination. Remove those current rows from this
                # exam's staffing view before applying the archived snapshot.
                # If no archived snapshot exists, the old cohort must correctly
                # display "No teacher allocated" rather than inheriting new staff.
                if exam_year:
                    try:
                        promoted_source_rows=tracker_cur.execute(
                            """SELECT DISTINCT from_class_id
                               FROM student_class_history
                               WHERE school_id=? AND CAST(from_academic_year AS INTEGER)=?
                                 AND CAST(to_academic_year AS INTEGER)>? AND from_class_id IS NOT NULL""",
                            (sid,exam_year,exam_year)
                        ).fetchall()
                        promoted_source_ids={int(x["from_class_id"]) for x in promoted_source_rows
                                             if x["from_class_id"] is not None}
                        for promoted_class_id in promoted_source_ids:
                            subjects_by_class.pop(promoted_class_id,None)
                            for allocation_key in list(teachers_by_class_subject):
                                if allocation_key[0]==promoted_class_id:
                                    teachers_by_class_subject.pop(allocation_key,None)
                    except Exception as cohort_history_exc:
                        print("MABALE_ICT TRACKER PROMOTED COHORT SCOPE WARNING:",repr(cohort_history_exc),flush=True)
                # Resolve teacher staffing against the exam year, not just the
                # current active allocation. Promotion history is recorded in the
                # promotion cycle year, which may be the year AFTER the exam year.
                # For each participating class, use the first archived promotion
                # snapshot from the exam year or a later cycle, so a later promotion
                # cannot overwrite the staffing that belonged to this exam cohort.
                if exam_year:
                    try:
                        historical_allocations=tracker_cur.execute("""SELECT h.cycle_year,h.class_id,h.subject_id,h.teacher_id,
                            COALESCE(NULLIF(trim(h.teacher_name),''),'Unassigned teacher') AS teacher_name,
                            h.reason,h.recorded_at
                            FROM teacher_allocation_history h
                            WHERE h.school_id=?
                              AND h.reason IN (
                                  'Cohort promoted to next class',
                                  'Destination class staffing replaced by promoted cohort',
                                  'Prior allocation retained for cohort promoted to next class',
                                  'Class cohort graduated'
                              )
                            ORDER BY h.class_id,h.cycle_year,h.subject_id,h.recorded_at,teacher_name""",(sid,)).fetchall()
                        # The first promotion snapshot ON OR AFTER the exam year is
                        # the staffing that belonged to the cohort sitting that exam.
                        # A class row is reused after promotion, so a later snapshot can
                        # belong to a different cohort and must never replace this one.
                        # If no later snapshot exists, use the latest snapshot at/before
                        # the exam year as the best available historical record.
                        cycles_by_class={}
                        for allocation in historical_allocations:
                            if allocation["class_id"] is None or allocation["subject_id"] is None:
                                continue
                            history_class_id=int(allocation["class_id"])
                            history_cycle=int(allocation["cycle_year"] or 0)
                            if participating_ids is not None and history_class_id not in participating_ids:
                                continue
                            if not history_cycle:
                                continue
                            cycles_by_class.setdefault(history_class_id,set()).add(history_cycle)
                        chosen_cycle_by_class={}
                        for history_class_id,cycles in cycles_by_class.items():
                            future_cycles=[year for year in cycles if year>=exam_year]
                            chosen_cycle_by_class[history_class_id]=min(future_cycles) if future_cycles else max(cycles)
                        # A class can have TWO snapshots in the same promotion cycle:
                        # its original staffing archived before an incoming cohort replaces
                        # it, and staffing archived again when that class is processed as a
                        # source. In a cascading promotion, the source snapshot may already
                        # contain the incoming cohort's teachers. Prefer the destination-
                        # replacement snapshot for that class/cycle because it preserves the
                        # teachers that belonged to the class before it was overwritten.
                        chosen_reason_by_class_cycle={}
                        for allocation in historical_allocations:
                            if allocation["class_id"] is None:
                                continue
                            history_class_id=int(allocation["class_id"])
                            history_cycle=int(allocation["cycle_year"] or 0)
                            if chosen_cycle_by_class.get(history_class_id)!=history_cycle:
                                continue
                            reason=str(allocation["reason"] or "")
                            key=(history_class_id,history_cycle)
                            priority=(3 if reason=="Destination class staffing replaced by promoted cohort" else
                                      2 if reason=="Prior allocation retained for cohort promoted to next class" else
                                      1 if reason in ("Cohort promoted to next class","Class cohort graduated") else 0)
                            if priority>chosen_reason_by_class_cycle.get(key,0):
                                chosen_reason_by_class_cycle[key]=priority
                        historical_subjects_by_class={}
                        historical_teachers_by_class_subject={}
                        for allocation in historical_allocations:
                            if allocation["class_id"] is None or allocation["subject_id"] is None:
                                continue
                            history_class_id=int(allocation["class_id"])
                            history_cycle=int(allocation["cycle_year"] or 0)
                            chosen=chosen_cycle_by_class.get(history_class_id)
                            if chosen is None or chosen!=history_cycle:
                                continue
                            reason=str(allocation["reason"] or "")
                            priority=(3 if reason=="Destination class staffing replaced by promoted cohort" else
                                      2 if reason=="Prior allocation retained for cohort promoted to next class" else
                                      1 if reason in ("Cohort promoted to next class","Class cohort graduated") else 0)
                            if priority!=chosen_reason_by_class_cycle.get((history_class_id,history_cycle),0):
                                continue
                            key=(history_class_id,int(allocation["subject_id"]))
                            historical_subjects_by_class.setdefault(key[0],set()).add(key[1])
                            teacher_name=str(allocation["teacher_name"] or "Unassigned teacher").strip()
                            teacher_names=historical_teachers_by_class_subject.setdefault(key,[])
                            if teacher_name and teacher_name not in teacher_names:
                                teacher_names.append(teacher_name)
                        # Archived rows replace current allocations only for classes
                        # actually covered by that historical snapshot.
                        for historical_class_id,historical_subject_ids in historical_subjects_by_class.items():
                            subjects_by_class[historical_class_id]=historical_subject_ids
                        for key,teacher_names in historical_teachers_by_class_subject.items():
                            teachers_by_class_subject[key]=teacher_names
                    except Exception as history_exc:
                        print("MABALE_ICT TRACKER HISTORICAL STAFFING WARNING:",repr(history_exc),flush=True)
                all_subject_rows=tracker_cur.execute("SELECT id,name FROM subjects WHERE school_id=? ORDER BY name",(sid,)).fetchall()
                subject_names={int(x["id"]):str(x["name"] or "Subject") for x in all_subject_rows}
                for tracker_class in participating_classes:
                    tracker_class_id=int(tracker_class["id"])
                    expected_subject_ids=sorted(subjects_by_class.get(tracker_class_id) or subject_names.keys(),key=lambda x:subject_names.get(x,"").casefold())
                    if exam_year:
                        active_row=tracker_cur.execute("""SELECT COUNT(DISTINCT cohort.student_id) AS n FROM (
                            SELECT st.id AS student_id FROM students st
                            WHERE st.school_id=? AND st.class_id=?
                              AND lower(coalesce(st.status,'active'))='active'
                              AND NOT EXISTS (SELECT 1 FROM student_graduations sg WHERE sg.school_id=st.school_id AND sg.student_id=st.id)
                              AND NOT EXISTS (SELECT 1 FROM student_class_history incoming
                                  WHERE incoming.school_id=st.school_id AND incoming.student_id=st.id
                                    AND incoming.to_class_id=? AND incoming.to_academic_year>?)
                            UNION
                            SELECT hist.student_id FROM student_class_history hist
                            WHERE hist.school_id=? AND hist.from_class_id=?
                              AND hist.from_academic_year=? AND hist.to_academic_year>?
                        ) cohort""",(sid,tracker_class_id,tracker_class_id,exam_year,sid,tracker_class_id,exam_year,exam_year)).fetchone()
                    else:
                        active_row=tracker_cur.execute("""SELECT COUNT(*) AS n FROM students st
                            WHERE st.school_id=? AND st.class_id=? AND lower(coalesce(st.status,'active'))='active'
                            AND NOT EXISTS (SELECT 1 FROM student_graduations sg WHERE sg.school_id=st.school_id AND sg.student_id=st.id)""",(sid,tracker_class_id)).fetchone()
                    active_count=int(active_row["n"] or 0) if active_row else 0
                    mark_rows=tracker_cur.execute("""SELECT subject_id,COUNT(DISTINCT student_id) AS entered
                        FROM marks WHERE school_id=? AND exam_id=? AND class_id=? GROUP BY subject_id""",(sid,tracker_exam_id,tracker_class_id)).fetchall()
                    entered_by_subject={int(m["subject_id"]):int(m["entered"] or 0) for m in mark_rows if m["subject_id"] is not None}
                    submitted_subjects=[x for x in expected_subject_ids if entered_by_subject.get(x,0)>0]
                    expected_count=len(expected_subject_ids)
                    submitted_count=len(submitted_subjects)
                    if expected_count and submitted_count==expected_count:
                        status_label="Completed"; status_class="complete"
                    elif submitted_count:
                        status_label="In progress"; status_class="progress"
                    else:
                        status_label="Pending"; status_class="pending"
                    subject_lines=[]
                    for subject_id in expected_subject_ids:
                        entered=entered_by_subject.get(subject_id,0)
                        subject_status="Submitted" if entered else "Pending"
                        subject_class="subject-done" if entered else "subject-pending"
                        teacher_names=teachers_by_class_subject.get((tracker_class_id,subject_id),[])
                        teacher_label=", ".join(teacher_names) if teacher_names else "No teacher allocated"
                        subject_lines.append("<div class='tracker-subject'><span>%s</span><span class='%s'>%s</span><small class='tracker-teacher'>Teacher: %s</small><small>%s/%s learners with marks</small></div>"%(escape(subject_names.get(subject_id,"Subject")),subject_class,subject_status,escape(teacher_label),entered,active_count))
                    if not expected_subject_ids:
                        subject_lines.append("<div class='tracker-subject'><span>No subjects configured</span><span class='subject-pending'>Pending</span></div>")
                    if tracker_class_id_filter and tracker_class_id != tracker_class_id_filter:
                        continue
                    if tracker_status_filter and status_class != tracker_status_filter:
                        continue
                    class_label=escape(str(tracker_class["name"] or "Class"))+" "+escape(str(tracker_class["stream"] or ""))
                    pct=int(submitted_count*100/expected_count) if expected_count else 0
                    tracker_rows.append("<tr class='tracker-class-row'><td colspan='2'><div class='tracker-class-summary'><div class='tracker-class-name'><b>%s</b></div><div class='tracker-overall'><span class='tracker-overall-label'>Overall status</span><span class='tracker-status %s'>%s</span><div class='tracker-bar'><span style='width:%s%%'></span></div><small>%s/%s subjects submitted</small></div></div><div class='tracker-subject-section'><h3>Subject submission status</h3><div class='tracker-subjects'>%s</div></div></td></tr>"%(class_label,status_class,status_label,pct,submitted_count,expected_count,"".join(subject_lines)))
            except Exception as tracker_exc:
                tracker_error="The tracker could not load for this examination. Existing academic functions remain available."
                print("MABALE_ICT EXAM SUBMISSION TRACKER WARNING:",repr(tracker_exc),flush=True)
            finally:
                tracker_con.close()
        tracker_table="<div class='tracker-table-wrap'><table class='tracker-table'><tbody>%s</tbody></table></div>"%("".join(tracker_rows) or "<tr><td colspan='2'>No classes match these filters for this examination.</td></tr>")
        tracker_message=("<p class='tracker-error'>"+escape(tracker_error)+"</p>") if tracker_error else ""
        tracker_form="<form method='get' action='/app/academics/submission-tracker' class='tracker-filter-form'>"+tracker_hidden+"<div class='tracker-filter'><label for='tracker-exam-select'>Examination</label><select id='tracker-exam-select' name='tracker_exam_id'>"+tracker_options+"</select></div><div class='tracker-filter'><label for='tracker-class-select'>Class / stream</label><select id='tracker-class-select' name='tracker_class_id'>"+tracker_class_options+"</select></div><div class='tracker-filter'><label for='tracker-status-select'>Submission status</label><select id='tracker-status-select' name='tracker_status'>"+tracker_status_options+"</select></div><button type='button' id='tracker-load-table' class='tracker-load-button'>Load table</button></form>"
        tracker_content=tracker_message if tracker_message else (tracker_table if tracker_load and tracker_exam else "<p class='muted tracker-prompt'>Choose your filters above, then click <b>Load table</b> to view submission status.</p>" if tracker_exam else "<p class='muted'>Create an examination to start tracking submissions.</p>")
        body+="<section class='section exam-submission-tracker'><div class='tracker-heading'><div><h2>Exam Submission Tracker</h2><p class='muted'>Select an examination and optional filters, then load the table when you are ready.</p></div></div>"+tracker_form+"<div class='tracker-results' "+("" if tracker_load else "hidden")+">"+tracker_content+"</div></section>"
