        ".marksheet-select{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.marksheet-select>details{grid-column:1/-1}.marksheet-select>label{display:grid;gap:6px;font-size:11px;font-weight:800;color:#536d5b}.subject-picker{grid-column:1/-1;border:1px solid #dbe2ea;border-radius:10px;padding:10px;background:#f8fafc}.subject-picker-title{font-weight:900;margin-bottom:8px}.subject-picker-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:7px 12px}.subject-picker-grid label{font-weight:600}.subject-picker-actions{margin-top:8px}.subject-metric-picker{grid-column:1/-1;border:1px solid #dbe2ea;border-radius:10px;padding:10px;background:#fff}.subject-metric-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:7px 14px}.metric-label{margin-left:6px;font-weight:600}.btn,.btnlink{padding:10px 14px;border:1px solid #dbe2ea;border-radius:9px;background:#111827;color:#fff;font-weight:800;text-decoration:none;cursor:pointer}.btnlink{background:#fff;color:#172033;margin:0}.marksheet-action-links{display:flex;flex-wrap:wrap;align-items:stretch;gap:8px;margin-top:10px}.marksheet-action-links .btnlink{display:inline-flex;align-items:center;justify-content:center;white-space:normal;line-height:1.25;text-align:center;min-height:42px}"
