@router.get("/app/academics/external-analysis/csv")
def external_exam_analysis_csv(request: Request, exam_type: str = "", year: str = "", exam_name: str = ""):
    sid = _school_session(request)
    if not sid:
        return RedirectResponse("/", status_code=303)
    if not _msa_require_school_admin(request, sid):
        return HTMLResponse("External examination analysis is available to the School Admin only.", status_code=403)
    con = _db()
    try:
        rows = _external_exam_scope_rows(con.cursor(),sid,exam_type.upper(),year,exam_name)
        con.close()
        return _external_exam_csv_response(rows,"Mabale_ICT_External_Examination_Results.csv")
    except Exception as exc:
        try: con.close()
        except Exception: pass
        print("MABALE_ICT EXTERNAL EXAM CSV FAILED:",repr(exc),flush=True)
        return HTMLResponse("Unable to export external examination results.",500)

@router.get("/app/academics/external-analysis/pdf")
def external_exam_analysis_pdf(request: Request, exam_type: str = "", year: str = "", exam_name: str = ""):
    sid = _school_session(request)
    if not sid:
        return RedirectResponse("/", status_code=303)
    if not _msa_require_school_admin(request, sid):
        return HTMLResponse("External examination analysis is available to the School Admin only.", status_code=403)
    con = _db()
    try:
        rows = _external_exam_scope_rows(con.cursor(),sid,exam_type.upper(),year,exam_name)
        school = con.cursor().execute("SELECT * FROM schools WHERE id=?",(sid,)).fetchone()
        con.close()
        from reportlab.lib import colors
        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.enums import TA_CENTER
        from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle
        from reportlab.lib.units import mm
        buffer = io.BytesIO()
        doc = SimpleDocTemplate(buffer,pagesize=landscape(A4),rightMargin=24,leftMargin=24,topMargin=24,bottomMargin=24)
        styles = getSampleStyleSheet()
        styles.add(ParagraphStyle(name="ExternalTitle",parent=styles["Title"],alignment=TA_CENTER,textColor=colors.HexColor("#145a34"),fontSize=16,leading=20))
        styles.add(ParagraphStyle(name="ExternalSmall",parent=styles["BodyText"],fontSize=7,leading=9))
        school_name = str(school["name"] or "Mabale_ICT") if school else "Mabale_ICT"
        title = "External Examination Analysis" + ((" - "+exam_type.upper()) if exam_type else "")
        story = [Paragraph(escape(school_name),styles["Heading2"]),Paragraph(escape(title),styles["ExternalTitle"]),
                 Paragraph(escape("Year: "+(year or "All years")+" · Examination: "+(exam_name or "All examinations")),styles["Normal"]),Spacer(1,10)]
        summary = _external_exam_report_summary(rows)
        story.append(Paragraph(escape("Unique candidates: %d · Candidates with scores: %d · Mean candidate percentage: %s"%
            (summary["candidates"],summary["assessed"],("%.2f%%"%summary["school_mean"]) if summary["school_mean"] is not None else "—")),styles["Normal"]))
        if summary["mean_points"] is not None:
            grade_label = _external_exam_school_mean_grade(summary["mean_points"]) if exam_type.upper() == "KCSE" else "not applicable to mixed / non-KCSE grading"
            story.append(Paragraph(escape("Mean grade points: %.2f · Indicative mean grade: %s"%
                (summary["mean_points"],grade_label)),styles["Normal"]))
        story.append(Spacer(1,8))
        story.append(Paragraph("Subject Performance",styles["Heading2"]))
        table_data = [["Subject","Candidates with scores","Mean %","Highest %","Lowest %"]]
        for item in summary["subject_rows"]:
            table_data.append([Paragraph(escape(item["name"]),styles["ExternalSmall"]),str(item["sat"]),
                ("%.2f%%"%item["mean"]) if item["mean"] is not None else "—",
                ("%.2f%%"%item["highest"]) if item["highest"] is not None else "—",
                ("%.2f%%"%item["lowest"]) if item["lowest"] is not None else "—"])
        subject_table = Table(table_data,repeatRows=1,colWidths=[250,115,100,100,100])
        subject_table.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#eaf4ed")),("TEXTCOLOR",(0,0),(-1,0),colors.HexColor("#245239")),
            ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("FONTSIZE",(0,0),(-1,-1),8),("GRID",(0,0),(-1,-1),0.35,colors.HexColor("#d9e5dc")),
            ("VALIGN",(0,0),(-1,-1),"TOP"),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#f8fbf9")]),("LEFTPADDING",(0,0),(-1,-1),5),("RIGHTPADDING",(0,0),(-1,-1),5)]))
        story.append(subject_table)
        story.append(Spacer(1,12))
        story.append(Paragraph("Candidate Performance",styles["Heading2"]))
        cand_data = [["Pos.","Candidate No.","Candidate","Gender","Subjects","Average %","Avg. points"]]
        for i,item in enumerate(summary["candidate_rows"],1):
            cand_data.append([str(i),Paragraph(escape(item["candidate_no"]),styles["ExternalSmall"]),
                Paragraph(escape(item["candidate_name"]),styles["ExternalSmall"]),item["gender"],str(item["subjects"]),
                ("%.2f%%"%item["average"]) if item["average"] is not None else "—",
                ("%.2f"%item["grade_points"]) if item["grade_points"] is not None else "—"])
        cand_table = Table(cand_data,repeatRows=1,colWidths=[35,95,180,50,55,80,70])
        cand_table.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#eaf4ed")),("TEXTCOLOR",(0,0),(-1,0),colors.HexColor("#245239")),
            ("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),("FONTSIZE",(0,0),(-1,-1),7),("GRID",(0,0),(-1,-1),0.35,colors.HexColor("#d9e5dc")),
            ("VALIGN",(0,0),(-1,-1),"TOP"),("ROWBACKGROUNDS",(0,1),(-1,-1),[colors.white,colors.HexColor("#f8fbf9")])]))
        story.append(cand_table)
        story.append(Spacer(1,10))
        story.append(Paragraph("Official grade / achievement-level distribution",styles["Heading2"]))
        gd = [["Official grade / level","Subject entries"]]+[[g,str(n)] for g,n in summary["grades"]]
        gt = Table(gd,repeatRows=1,colWidths=[180,110])
        gt.setStyle(TableStyle([("BACKGROUND",(0,0),(-1,0),colors.HexColor("#eaf4ed")),("FONTNAME",(0,0),(-1,0),"Helvetica-Bold"),
            ("FONTSIZE",(0,0),(-1,-1),8),("GRID",(0,0),(-1,-1),0.35,colors.HexColor("#d9e5dc"))]))
        story.append(gt)
        story.append(Spacer(1,8))
        story.append(Paragraph("Official grades/levels are retained as entered or imported. This report is an analysis aid and does not replace official KNEC grade calculations or candidate eligibility rules.",styles["ExternalSmall"]))
        def draw_export_footer(canvas, document):
            canvas.saveState()
            canvas.setFont("Helvetica", 7)
            canvas.setFillColor(colors.HexColor("#176b3a"))
            generated_at = datetime.now(ZoneInfo("Africa/Nairobi")).strftime("%d/%m/%Y %H:%M EAT")
            canvas.drawCentredString(landscape(A4)[0] / 2, 3 * mm, "Mabale_ICT Software · Generated: " + generated_at + " · Page %d" % canvas.getPageNumber())
            canvas.restoreState()
        doc.build(story, onFirstPage=draw_export_footer, onLaterPages=draw_export_footer)
        return Response(buffer.getvalue(),media_type="application/pdf",
                        headers={"Content-Disposition":'attachment; filename="Mabale_ICT_External_Examination_Analysis.pdf"'})
    except Exception as exc:
        try: con.close()
        except Exception: pass
        print("MABALE_ICT EXTERNAL EXAM PDF FAILED:",repr(exc),flush=True)
        return HTMLResponse("Unable to generate the external examination analysis PDF. Please check the application logs.",500)


@router.get("/app/academics/analysis", response_class=HTMLResponse)
def new_analysis(
    request: Request, exam_id: str = "", exam_ids: str = "", class_id: str = "",
    year: str = "", term: str = "", class_name: str = "", stream: str = "",
    student_id: str = "", view: str = "summary"
):
    # Academic Analysis is the full Class MarkSheet Analysis page, not a separate
    # landing page. Reuse the same report logic and keep its filters/views intact.
    selected_ids = exam_ids or exam_id
    return class_marksheet_analysis(
        request, exam_ids=selected_ids, year=year, term=term,
        class_name=class_name, stream=stream, student_id=student_id, view=view
    )


@router.post("/app/report-cards/overall-grade-comments")
async def save_overall_grade_comments(request: Request):
    sid=_school_session(request)
    if not sid:return RedirectResponse("/",303)
    if not _require_permission(request, sid, "reports.edit"):
        return HTMLResponse("You do not have permission to edit overall-grade report card comments.",403)
    try:
        form=await request.form()
        rule_id=int(str(form.get("rule_id") or "0"))
        class_teacher_comment=str(form.get("class_teacher_comment") or "").strip()
        principal_comment=str(form.get("principal_comment") or "").strip()
    except Exception:
        return HTMLResponse("Invalid overall-grade comment submission. <a href='/app/academics/overall-grading'>Back</a>",400)
    con=_db()
    cur=con.cursor()
    try:
        _ensure_overall_grading_table(cur)
        rule=cur.execute("SELECT id FROM overall_grading_rules WHERE id=? AND school_id=?",(rule_id,sid)).fetchone()
        if not rule:
            con.rollback()
            return HTMLResponse("Overall grading rule not found. <a href='/app/academics/overall-grading'>Back</a>",404)
        cur.execute("UPDATE overall_grading_rules SET class_teacher_comment=?, principal_comment=? WHERE id=? AND school_id=?",
                    (class_teacher_comment,principal_comment,rule_id,sid))
        _audit(cur,sid,request,"OVERALL_GRADE_REPORT_COMMENTS",
               "Updated grade-based report card comments for rule %s" % rule_id)
        con.commit()
        saved=cur.execute("SELECT class_teacher_comment,principal_comment FROM overall_grading_rules WHERE id=? AND school_id=?",
                          (rule_id,sid)).fetchone()
        if not saved or str(saved["class_teacher_comment"] or "") != class_teacher_comment or str(saved["principal_comment"] or "") != principal_comment:
            con.rollback()
            return HTMLResponse("The overall-grade comments could not be saved to the database. <a href='/app/academics/overall-grading'>Back</a>",500)
    except Exception as exc:
        try: con.rollback()
        except Exception: pass
        print("MABALE_ICT OVERALL GRADE COMMENTS SAVE ERROR:",repr(exc),flush=True)
        return HTMLResponse("Mabale_ICT could not save the overall-grade comments. Technical detail: %s <a href='/app/academics/overall-grading'>Back</a>" % escape(str(exc)),500)
    finally:
        try: con.close()
        except Exception: pass
    return RedirectResponse("/app/academics/overall-grading",303)


@router.post("/app/report-cards/subject-comment")
def save_subject_comment(request: Request, student_id:int=Form(...), exam_id:int=Form(...), subject_id:int=Form(...), comment:str=Form("")):
    sid=_school_session(request)
    if not sid:return RedirectResponse("/",303)
    if not _require_permission(request, sid, "reports.edit"):
        return HTMLResponse("You do not have permission to edit report comments.", 403)
    con=_db();cur=con.cursor();_ensure_report_card_fields(cur)
    valid=cur.execute("SELECT id FROM students WHERE id=? AND school_id=?",(student_id,sid)).fetchone() and cur.execute("SELECT id FROM subjects WHERE id=? AND school_id=?",(subject_id,sid)).fetchone() and cur.execute("SELECT id FROM exams WHERE id=? AND school_id=?",(exam_id,sid)).fetchone()
    if not valid: con.close(); return HTMLResponse("Invalid report selection.",400)
    now=datetime.now(ZoneInfo("Africa/Nairobi")).strftime("%Y-%m-%d %H:%M:%S")
    cur.execute("INSERT INTO subject_performance_comments(school_id,student_id,exam_id,subject_id,comment,updated_at) VALUES(?,?,?,?,?,?) ON CONFLICT(school_id,student_id,exam_id,subject_id) DO UPDATE SET comment=excluded.comment,updated_at=excluded.updated_at",
                (sid,student_id,exam_id,subject_id,comment.strip(),now))
    con.commit();con.close()
    return RedirectResponse(f"/app/report-cards?student_id={student_id}&exam_id={exam_id}",303)

