@router.get("/app/admission-letters/{application_id}", response_class=HTMLResponse)
def admission_letter_print(request: Request, application_id: int):
    sid, denied = _admission_guard(request)
    if denied: return denied
    con = _db()
    try:
        app_row = con.execute(
            "SELECT * FROM admission_applications WHERE id=? AND school_id=?",
            (application_id, sid)
        ).fetchone()
        if not app_row:
            return HTMLResponse("Admission letter not found.", 404)
        student = None
        if app_row["enrolled_student_id"]:
            student = con.execute(
                "SELECT * FROM students WHERE id=? AND school_id=?",
                (app_row["enrolled_student_id"], sid)
            ).fetchone()
        if not student:
            return HTMLResponse("The enrolled learner record could not be found.", 404)
        class_row = con.execute(
            "SELECT name,stream FROM classes WHERE id=? AND school_id=?",
            (student["class_id"], sid)
        ).fetchone() if student["class_id"] else None
        school = con.execute("SELECT * FROM schools WHERE id=?", (sid,)).fetchone()
    finally:
        con.close()

    def _letter_get(record, key, fallback=""):
        try:
            value = record[key] if record is not None and key in record.keys() else None
        except Exception:
            value = None
        return str(value).strip() if value is not None and str(value).strip() else fallback

    def _letter_cell(label, value, wide=False):
        value = str(value or "").strip()
        if not value:
            return ""
        return (
            "<div class='letter-field" + (" wide" if wide else "") + "'>"
            "<span>" + escape(str(label)) + "</span><strong>" + escape(value) + "</strong></div>"
        )

    learner_name = _letter_get(student, "name", _letter_get(app_row, "applicant_name", "Learner"))
    admission_no = _letter_get(student, "admission_no", _letter_get(app_row, "admission_no"))
    assessment_no = _letter_get(student, "assessment_no")
    class_name = _letter_get(class_row, "name", "—")
    class_stream = _letter_get(class_row, "stream", _letter_get(student, "stream"))
    parent_name = _letter_get(student, "parent_name",
        _letter_get(student, "guardian_name", _letter_get(app_row, "parent_name", "Parent / Guardian")))
    parent_phone = _letter_get(student, "parent_phone",
        _letter_get(student, "guardian_phone", _letter_get(app_row, "parent_phone")))
    parent_email = _letter_get(student, "parent_email",
        _letter_get(student, "guardian_email", _letter_get(app_row, "parent_email")))
    school_name = _letter_get(school, "name", "Mabale_ICT")
    school_level = _letter_get(school, "school_type")
    school_location = _letter_get(school, "location")
    school_phone = _letter_get(school, "phone")
    school_email = _letter_get(school, "email")
    school_postal = " ".join(part for part in (
        ("P.O. Box " + _letter_get(school, "postal_address")) if _letter_get(school, "postal_address") else "",
        _letter_get(school, "postal_code")
    ) if part)
    school_logo = _letter_get(school, "logo_data")
    if school_logo and not school_logo.startswith(("data:", "http://", "https://", "/")):
        school_logo = "data:image/png;base64," + school_logo
    logo_html = (
        "<img class='school-logo' src='" + escape(school_logo, quote=True) + "' alt='School logo'>"
        if school_logo else "<div class='logo-placeholder'>" + escape(school_name[:2].upper()) + "</div>"
    )
    school_contacts = " · ".join(value for value in (
        school_postal,
        ("Tel: " + school_phone) if school_phone else "",
        ("Email: " + school_email) if school_email else ""
    ) if value)

    # Include all learner/guardian details actually stored on the enrolled student
    # record, while omitting database identifiers and system-maintained metadata.
    student_labels = {
        "name": "Full name", "admission_no": "Admission number",
        "assessment_no": "Assessment number", "gender": "Gender",
        "date_of_birth": "Date of birth", "dob": "Date of birth",
        "birth_date": "Date of birth", "birth_certificate_no": "Birth certificate number",
        "upi": "UPI number", "parent_name": "Parent / Guardian",
        "guardian_name": "Parent / Guardian", "parent_phone": "Parent / Guardian phone",
        "guardian_phone": "Alternative guardian phone", "parent_email": "Parent / Guardian email",
        "guardian_email": "Alternative guardian email", "relationship": "Relationship to learner",
        "parent_relationship": "Relationship to learner", "address": "Residential address",
        "home_address": "Residential address", "residence": "Residence",
        "county": "County", "sub_county": "Sub-county", "village": "Village / Estate",
        "emergency_contact": "Emergency contact", "emergency_phone": "Emergency phone",
        "category": "Student category", "student_category": "Student category",
        "status": "Learner status"
    }
    excluded_student_columns = {
        "id", "school_id", "class_id", "created_at", "updated_at",
        "password", "password_hash", "session_token", "deleted_at"
    }
    ordered_student_keys = [
        "name", "admission_no", "assessment_no", "gender", "date_of_birth", "dob",
        "birth_date", "birth_certificate_no", "upi", "parent_name", "guardian_name",
        "parent_phone", "guardian_phone", "parent_email", "guardian_email",
        "relationship", "parent_relationship", "address", "home_address", "residence",
        "county", "sub_county", "village", "emergency_contact", "emergency_phone",
        "category", "student_category", "status"
    ]
    student_keys = list(student.keys())
    ordered_student_keys = [key for key in ordered_student_keys if key in student_keys]
    extra_student_keys = [
        key for key in student_keys
        if key not in ordered_student_keys and key not in excluded_student_columns
        and not key.endswith("_id") and not key.endswith("_at")
        and not key.lower().startswith(("password", "token", "secret"))
    ]
    student_fields = []
    seen_student_labels = set()
    for key in ordered_student_keys + extra_student_keys:
        value = _letter_get(student, key)
        if not value:
            continue
        label = student_labels.get(key, key.replace("_", " ").strip().title())
        if label in seen_student_labels:
            continue
        seen_student_labels.add(label)
        if key in ("address", "home_address", "residence"):
            student_fields.append(_letter_cell(label, value, True))
        else:
            student_fields.append(_letter_cell(label, value))

    application_fields = []
    application_items = [
        ("Application date", _letter_get(app_row, "application_date")),
        ("Previous school", _letter_get(app_row, "previous_school")),
        ("Application notes / additional information", _letter_get(app_row, "notes"))
    ]
    for label, value in application_items:
        if value:
            application_fields.append(_letter_cell(label, value, label.endswith("information")))

    letter_date = datetime.now(ZoneInfo("Africa/Nairobi")).strftime("%d %B %Y")
    body = f"""<div class='page letter-page'>
      <div class='letter-tools'><a href='/app/admission-letters'>Back to Admission Letters</a><button type='button' onclick='openAdmissionPrintPreview()'>Open Print Preview / Save PDF</button></div>
      <article class='letter-paper'>
        <header class='letter-header'>
          <div class='letter-brand'><div class='letter-logo-left'>{logo_html}</div><div class='letter-school-name'><h1>{escape(school_name)}</h1><p>{escape(school_contacts)}</p></div><div class='letter-logo-right'>{logo_html}</div></div>
          <div class='letter-rule'></div>
          <div class='letter-meta'><span>OFFICIAL SCHOOL COMMUNICATION</span><span>DATE: {escape(letter_date)}</span></div>
        </header>
        <h2>NOTICE OF ADMISSION</h2>
        <p class='letter-reference'>Admission confirmation · Ref: {escape(admission_no or str(application_id))}</p>
        <p>Dear <strong>{escape(parent_name)}</strong>,</p>
        <p>We are pleased to formally notify you that <strong>{escape(learner_name)}</strong> has been admitted to our <strong>{escape(school_level)}</strong> institution in <strong>{escape((class_name + (' - ' + class_stream if class_stream else '')).upper())}</strong> at <strong>{escape(school_name.upper())}</strong>.</p>
        <p>This notice confirms the learner's admission and provides the registration particulars for your reference. Kindly review the details below and retain this document for future correspondence with the school.</p>
        <section class='letter-section'><h3>LEARNER PARTICULARS</h3><div class='letter-grid'>{''.join(student_fields)}</div></section>
        <section class='letter-section'><h3>PARENT / GUARDIAN CONTACT</h3><div class='letter-grid'>
          {_letter_cell("Parent / Guardian name", parent_name)}
          {_letter_cell("Phone number", parent_phone)}
          {_letter_cell("Email address", parent_email, True)}
        </div></section>
        <section class='letter-section'><h3>ADMISSION RECORD</h3><div class='letter-grid'>
          {_letter_cell("Admission number", admission_no)}
          {_letter_cell("Assessment number", assessment_no)}
          {_letter_cell("Admitted class", class_name)}
          {_letter_cell("Stream", class_stream)}
          {''.join(application_fields)}
        </div></section>
        <p class='letter-instructions'>The school will communicate any further reporting instructions through the parent / guardian contact details provided above.</p>
        <div class='letter-signoff'><div><p>Yours faithfully,</p><div class='signature-space'></div><strong>School Administration</strong><span>For and on behalf of {escape(school_name)}</span></div><div class='stamp-space'>OFFICIAL<br> SCHOOL STAMP</div></div>
        <footer class='letter-footer'>This is an official admission record generated from the learner's saved registration details.</footer>
      </article>
    </div>
    <style>
      .letter-page{{max-width:100%;padding:0 10px 24px;box-sizing:border-box}}
      .letter-tools{{display:flex;justify-content:space-between;gap:10px;margin:0 auto 14px;max-width:210mm}}
      .letter-tools a,.letter-tools button{{border:0;border-radius:8px;padding:10px 14px;background:#e4f3e7;color:#176b3a;text-decoration:none;font-weight:800;cursor:pointer}}
      .letter-tools button{{background:#176b3a;color:#fff}}
      .letter-paper{{box-sizing:border-box;background:#fff;color:#263d2b;width:210mm;min-height:297mm;margin:0 auto;padding:17mm 18mm 15mm;border:1px solid #dbe7dc;box-shadow:0 5px 24px rgba(20,65,35,.10);font-family:Arial,sans-serif;font-size:10.5pt;line-height:1.48;display:flex;flex-direction:column}}
      .letter-header{{border-bottom:2px solid #176b3a;padding-bottom:7mm}}
      .letter-brand{{display:grid;grid-template-columns:22mm minmax(0,1fr) 22mm;align-items:center;gap:8mm;text-align:center}}
      .letter-logo-left,.letter-logo-right{{display:flex;align-items:center;justify-content:center;min-width:0}}
      .letter-school-name{{min-width:0}}
      .school-logo{{width:22mm;height:22mm;object-fit:contain}}
      .logo-placeholder{{width:22mm;height:22mm;border-radius:50%;background:#e7f1e7;color:#176b3a;display:flex;align-items:center;justify-content:center;font-size:18pt;font-weight:900}}
      .letter-brand h1{{font-size:20pt;color:#176b3a;margin:0 0 3px;line-height:1.15}}
      .letter-brand p{{font-size:8.5pt;color:#65786a;margin:0;line-height:1.4}}
      .letter-rule{{height:3px;background:#b5d7bc;margin-top:5mm}}
      .letter-meta{{display:flex;justify-content:space-between;gap:10px;margin-top:3mm;font-size:8pt;font-weight:800;color:#54715b;letter-spacing:.5px}}
      .letter-paper h2{{text-align:center;color:#174b2b;font-size:16pt;letter-spacing:1px;margin:8mm 0 2mm}}
      .letter-reference{{text-align:center;color:#647768;font-size:8.5pt;margin:0 0 6mm}}
      .letter-paper>p{{margin:0 0 4mm}}
      .letter-section{{margin-top:5mm;break-inside:avoid}}
      .letter-section h3{{font-size:9pt;letter-spacing:.7px;color:#176b3a;border-bottom:1px solid #c9ddcc;padding:0 0 2mm;margin:0 0 3mm}}
      .letter-grid{{display:grid;grid-template-columns:1fr 1fr;gap:2.5mm 8mm}}
      .letter-field{{display:flex;flex-direction:column;gap:1px;min-width:0;padding:1mm 0 2mm;border-bottom:1px solid #edf2ed;overflow-wrap:anywhere}}
      .letter-field.wide{{grid-column:1/-1}}
      .letter-field span{{font-size:7.5pt;text-transform:uppercase;letter-spacing:.35px;color:#718276;font-weight:700}}
      .letter-field strong{{font-size:9.5pt;font-weight:700;color:#263d2b}}
      .letter-instructions{{margin-top:6mm!important;text-align:justify}}
      .letter-signoff{{display:flex;justify-content:space-between;align-items:flex-end;gap:12mm;margin-top:auto;padding-top:8mm;break-inside:avoid}}
      .letter-signoff p{{margin:0 0 2mm}}
      .signature-space{{height:13mm;border-bottom:1px solid #718276;width:58mm;margin-bottom:2mm}}
      .letter-signoff strong,.letter-signoff span{{display:block;font-size:9pt}}
      .letter-signoff span{{font-size:8pt;color:#687c6d;margin-top:1mm}}
      .stamp-space{{width:34mm;height:27mm;border:1px dashed #9eb5a2;border-radius:4px;display:flex;align-items:center;justify-content:center;text-align:center;color:#8a9c8e;font-size:8pt;font-weight:800;letter-spacing:1px}}
      .letter-footer{{border-top:1px solid #cbdccc;margin-top:7mm;padding-top:3mm;text-align:center;color:#718276;font-size:7.5pt}}
      @page{{size:A4 portrait;margin:0}}
      @media(max-width:760px){{.letter-paper{{width:100%;min-height:0;padding:24px 20px}}.letter-brand{{grid-template-columns:16mm minmax(0,1fr) 16mm;gap:3mm}}.school-logo,.logo-placeholder{{width:16mm;height:16mm}}.letter-brand h1{{font-size:17pt}}.letter-grid{{gap:8px 12px}}}}
      @media print{{
        html,body{{margin:0!important;padding:0!important;background:#fff!important}}
        .letter-page{{margin:0!important;padding:0!important;max-width:none!important}}
        .letter-tools{{display:none!important}}
        .letter-paper{{width:210mm!important;min-height:297mm!important;height:auto!important;margin:0!important;padding:17mm 18mm 15mm!important;border:0!important;border-radius:0!important;box-shadow:none!important;page-break-after:avoid;break-after:avoid}}
        .letter-section,.letter-signoff{{break-inside:avoid;page-break-inside:avoid}}
        *{{-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}}
      }}
    </style>"""
    # Return a clean, standalone print document rather than embedding it in the
    # application shell. This prevents dashboard overlays/layout scripts from
    # interfering with the browser's native print preview.
    auto_print = str(request.query_params.get("print", "")).strip() == "1"
    print_script = (
        "<script>\n"
        "function openAdmissionPrintPreview(){try{window.focus();window.print();}catch(e){console.error('Unable to open print preview',e);}}\n"
        + ("window.addEventListener('load',function(){setTimeout(openAdmissionPrintPreview,700);});" if auto_print else "")
        + "\n</script>"
    )
    document = (
        "<!doctype html><html lang='en'><head><meta charset='utf-8'>"
        "<meta name='viewport' content='width=device-width, initial-scale=1'>"
        "<meta name='color-scheme' content='light'><title>Notice of Admission</title>"
        "</head><body>" + body + print_script + "</body></html>"
    )
    return HTMLResponse(document)


@router.get("/app/admission-reports", response_class=HTMLResponse)
def admission_reports_page(request: Request, year: str = "", class_id: str = ""):
    sid, denied = _admission_guard(request)
    if denied: return denied
    year = year.strip() if re.fullmatch(r"[0-9]{4}", str(year or "").strip()) else ""
    class_id = class_id.strip() if str(class_id or "").isdigit() else ""
    con = _db(); cur = con.cursor()
    try:
        _ensure_admissions_schema(cur)
        where = "school_id=?"
        params = [sid]
        if year:
            where += " AND substr(CAST(COALESCE(application_date,'') AS TEXT),1,4)=?"
            params.append(year)
        if class_id:
            where += " AND applying_class_id=?"
            params.append(int(class_id))
        counts = cur.execute("SELECT lower(status) status,COUNT(*) total FROM admission_applications WHERE " + where + " GROUP BY lower(status)",params).fetchall()
        classes = cur.execute("SELECT id,name,stream FROM classes WHERE school_id=? ORDER BY name,stream",(sid,)).fetchall()
        # Avoid backend-specific substring/DISTINCT ordering behaviour here.
        # Application dates may be stored as text or native date values on older databases.
        date_rows = cur.execute("SELECT application_date FROM admission_applications WHERE school_id=? AND application_date IS NOT NULL",(sid,)).fetchall()
        available_years = set()
        for date_row in date_rows:
            date_value = str(date_row["application_date"] or "").strip()
            match = re.match(r"^(\d{4})", date_value)
            if match:
                available_years.add(match.group(1))
        years = [{"year": value} for value in sorted(available_years, reverse=True)]
        con.commit()
    finally:
        con.close()
    values = {str(row["status"] or ""):int(row["total"] or 0) for row in counts}
    year_options = "<option value=''>All years</option>" + "".join(f"<option value='{escape(str(r['year'] or ''),quote=True)}' {'selected' if str(r['year'] or '')==year else ''}>{escape(str(r['year'] or ''))}</option>" for r in years if r["year"])
    class_options = "<option value=''>All classes</option>" + "".join(f"<option value='{int(c['id'])}' {'selected' if str(c['id'])==class_id else ''}>{escape(str(c['name'] or '') + (' - ' + str(c['stream']) if c['stream'] else ''))}</option>" for c in classes)
    body = f"""<div class='page adm-page'><div class='adm-heading'><div><h1>Admission Reports</h1><p>Summary of applications and enrolment progress for this school.</p></div><button type='button' class='adm-popup-trigger adm-report-filter-trigger'>Filter report</button></div>
      <div class='adm-report-grid'><div><small>Total Applications</small><strong>{sum(values.values())}</strong></div>
      <div><small>Pending Review</small><strong>{values.get('pending',0)}</strong></div>
      <div><small>Accepted</small><strong>{values.get('accepted',0)}</strong></div>
      <div><small>Rejected</small><strong>{values.get('rejected',0)}</strong></div>
      <div><small>Enrolled</small><strong>{values.get('enrolled',0)}</strong></div></div>
      <form class='adm-report-filter-form' method='get' action='/app/admission-reports' style='display:grid;gap:12px'>
      <label>Application year<select name='year'>{year_options}</select></label>
      <label>Class / Stream<select name='class_id'>{class_options}</select></label>
      <div class='adm-popup-actions'><a href='/app/admission-reports' class='adm-popup-cancel' style='text-decoration:none;padding:10px 15px;border-radius:9px'>Clear filters</a></div>
      </form></div>
      <style>.adm-page{{max-width:1200px}}.adm-heading{{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}}.adm-heading h1{{margin:0;color:#174b2b}}.adm-heading p{{color:#687c6d}}.adm-report-grid{{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:12px}}.adm-report-grid>div{{background:#fff;border:1px solid #dce9de;border-radius:13px;padding:18px;display:grid;gap:8px}}.adm-report-grid small{{font-size:11px;color:#6b7e6d;font-weight:800}}.adm-report-grid strong{{font-size:25px;color:#176b3a}}.adm-report-filter-form{{display:none}}.adm-report-filter-form label{{display:grid;gap:6px;color:#46634b;font-size:12px;font-weight:850}}.adm-report-filter-form select{{padding:11px;border:1px solid #c7d9c8;border-radius:9px;background:#fff}}@media(max-width:800px){{.adm-report-grid{{grid-template-columns:repeat(2,minmax(0,1fr))}}}}</style>"""
    body += _admission_ui_enhancements()
    return _school_page(request,"Admission Reports",body)


# ---------------------------------------------------------------------------
# Finance & Accounts: integrated billing, collections, payables, ledger,
# banking, budgets and reporting. Additive tables preserve legacy records.
# ---------------------------------------------------------------------------
def _finance_workspace_schema(cur, sid):
    cur.execute("""CREATE TABLE IF NOT EXISTS ds_fin_accounts(
        school_id INTEGER NOT NULL, code TEXT NOT NULL, name TEXT NOT NULL,
        account_type TEXT NOT NULL, opening_balance REAL NOT NULL DEFAULT 0,
        active INTEGER NOT NULL DEFAULT 1, PRIMARY KEY(school_id,code))""")
    cur.execute("""CREATE TABLE IF NOT EXISTS ds_fin_journals(
        id TEXT PRIMARY KEY, school_id INTEGER NOT NULL, journal_date TEXT NOT NULL,
        reference TEXT, description TEXT NOT NULL, status TEXT NOT NULL,
        created_by TEXT, created_at TEXT NOT NULL, approved_by TEXT, posted_at TEXT)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS ds_fin_journal_lines(
        id TEXT PRIMARY KEY, school_id INTEGER NOT NULL, journal_id TEXT NOT NULL,
        account_code TEXT NOT NULL, debit REAL NOT NULL DEFAULT 0,
        credit REAL NOT NULL DEFAULT 0, memo TEXT)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS ds_fin_suppliers(
        id TEXT PRIMARY KEY, school_id INTEGER NOT NULL, name TEXT NOT NULL,
        phone TEXT, email TEXT, tax_pin TEXT, created_at TEXT NOT NULL)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS ds_fin_bills(
        id TEXT PRIMARY KEY, school_id INTEGER NOT NULL, supplier_id TEXT NOT NULL,
        invoice_no TEXT NOT NULL, bill_date TEXT NOT NULL, due_date TEXT,
        description TEXT, amount REAL NOT NULL, status TEXT NOT NULL,
        created_at TEXT NOT NULL, paid_at TEXT)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS ds_fin_bank_accounts(
        id TEXT PRIMARY KEY, school_id INTEGER NOT NULL, bank_name TEXT NOT NULL,
        account_name TEXT NOT NULL, account_number TEXT, opening_balance REAL NOT NULL DEFAULT 0,
        created_at TEXT NOT NULL)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS ds_fin_bank_lines(
        id TEXT PRIMARY KEY, school_id INTEGER NOT NULL, account_id TEXT NOT NULL,
        line_date TEXT NOT NULL, reference TEXT, description TEXT, amount REAL NOT NULL,
        direction TEXT NOT NULL, reconciled INTEGER NOT NULL DEFAULT 0, cashbook_id TEXT)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS ds_fin_budgets(
        id TEXT PRIMARY KEY, school_id INTEGER NOT NULL, budget_year TEXT NOT NULL,
        department TEXT NOT NULL, account_code TEXT, amount REAL NOT NULL,
        created_at TEXT NOT NULL)""")
    cur.execute("""CREATE TABLE IF NOT EXISTS ds_fin_periods(
        school_id INTEGER NOT NULL, period_start TEXT NOT NULL, period_end TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'Open', closed_by TEXT, closed_at TEXT,
        PRIMARY KEY(school_id,period_start,period_end))""")
    cur.execute("""CREATE TABLE IF NOT EXISTS ds_fin_source_posts(
        school_id INTEGER NOT NULL, source_type TEXT NOT NULL, source_id TEXT NOT NULL,
        journal_id TEXT NOT NULL, created_at TEXT NOT NULL,
        PRIMARY KEY(school_id,source_type,source_id))""")
    cur.execute("""CREATE TABLE IF NOT EXISTS ds_fin_reversals(
        school_id INTEGER NOT NULL, original_journal_id TEXT NOT NULL,
        reversal_journal_id TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL,
        PRIMARY KEY(school_id,original_journal_id))""")
    cur.execute("""CREATE TABLE IF NOT EXISTS ds_fin_bank_imports(
        id TEXT PRIMARY KEY, school_id INTEGER NOT NULL, account_id TEXT NOT NULL,
        filename TEXT, imported_rows INTEGER NOT NULL DEFAULT 0,
        duplicate_rows INTEGER NOT NULL DEFAULT 0, imported_by TEXT, imported_at TEXT NOT NULL)""")
    seed = [
        ("1000","Cash on Hand","Asset"),("1010","Bank Accounts","Asset"),
        ("1020","Mobile Money Clearing","Asset"),("1100","Fee Receivables","Asset"),
        ("2000","Accounts Payable","Liability"),("3000","Accumulated Funds","Equity"),
        ("4000","School Income","Income"),("4100","Other Income","Income"),
        ("5000","Staff Costs","Expense"),("5100","Utilities","Expense"),
        ("5200","Learning Materials","Expense"),("5300","Repairs & Maintenance","Expense"),
        ("5400","Transport & Operations","Expense"),("5900","Other Expenses","Expense")
    ]
    for code,name,kind in seed:
        cur.execute("INSERT INTO ds_fin_accounts(school_id,code,name,account_type) SELECT ?,?,?,? WHERE NOT EXISTS (SELECT 1 FROM ds_fin_accounts WHERE school_id=? AND code=?)",
                    (sid,code,name,kind,sid,code))


def _finance_now():
    return datetime.now(ZoneInfo("Africa/Nairobi")).strftime("%Y-%m-%d %H:%M:%S")


def _finance_uid():
    import uuid
    return uuid.uuid4().hex


def _finance_access(request):
    sid = _school_session(request)
    if not sid:
        return None
    role = str(request.session.get("role") or "")
    if role not in ("school_admin","registrar"):
        return None
    if not (_require_permission(request,sid,"finance.view") or _require_permission(request,sid,"fees.view")):
        return None
    return sid


def _finance_prepare(cur, sid):
    _finance_workspace_schema(cur, sid)

def _finance_period_open(cur, sid, day):
    day = str(day or _finance_now())[:10]
    row = cur.execute("SELECT 1 FROM ds_fin_periods WHERE school_id=? AND status='Closed' AND ? BETWEEN period_start AND period_end LIMIT 1",(sid,day)).fetchone()
    return row is None


def _finance_post_source(cur, sid, day, reference, description, debit_code, credit_code, amount, actor, source_type, source_id):
    amount = round(float(amount or 0),2)
    if amount <= 0:
        return None
    existing = cur.execute("SELECT journal_id FROM ds_fin_source_posts WHERE school_id=? AND source_type=? AND source_id=?",(sid,source_type,str(source_id))).fetchone()
    if existing:
        return str(existing["journal_id"])
    if not _finance_period_open(cur,sid,day):
        raise ValueError("The accounting period is closed for this transaction date.")
    codes = cur.execute("SELECT code FROM ds_fin_accounts WHERE school_id=? AND active=1 AND code IN (?,?)",(sid,debit_code,credit_code)).fetchall()
    if len(codes) != 2:
        raise ValueError("Posting accounts are not available in this school's chart of accounts.")
    jid = _finance_uid()
    stamp = _finance_now()
    cur.execute("INSERT INTO ds_fin_journals(id,school_id,journal_date,reference,description,status,created_by,created_at,approved_by,posted_at) VALUES(?,?,?,?,?,?,?,?,?,?)",
        (jid,sid,day,reference or "",description,"Posted",actor,stamp,actor,stamp))
    cur.execute("INSERT INTO ds_fin_journal_lines(id,school_id,journal_id,account_code,debit,credit,memo) VALUES(?,?,?,?,?,?,?)",
        (_finance_uid(),sid,jid,debit_code,amount,0,description))
    cur.execute("INSERT INTO ds_fin_journal_lines(id,school_id,journal_id,account_code,debit,credit,memo) VALUES(?,?,?,?,?,?,?)",
        (_finance_uid(),sid,jid,credit_code,0,amount,description))
    cur.execute("INSERT INTO ds_fin_source_posts(school_id,source_type,source_id,journal_id,created_at) VALUES(?,?,?,?,?) RETURNING source_id",
        (sid,source_type,str(source_id),jid,stamp))
    return jid


def _finance_expense_account(category):
    value = str(category or "").lower()
    if any(x in value for x in ("staff","salary","payroll","wage")): return "5000"
    if any(x in value for x in ("utilit","electric","water","internet")): return "5100"
    if any(x in value for x in ("learning","book","stationery","material")): return "5200"
    if any(x in value for x in ("repair","maintenance")): return "5300"
    if any(x in value for x in ("transport","fuel","travel")): return "5400"
    return "5900"



def _finance_interaction_enhancements():
    return """
    <style>
      .fx-workspace .fx-action-row{display:flex;justify-content:flex-end;gap:8px;flex-wrap:wrap;margin:0 0 12px}
      .fx-workspace .fx-open-modal{border:0;border-radius:9px;padding:10px 15px;background:#176b3d;color:#fff;font-weight:800;cursor:pointer}
      .fx-workspace .fx-open-modal:hover{background:#12552f}
      .fx-workspace .fx-filterbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:0 0 12px}
      .fx-workspace .fx-filterbar input,.fx-workspace .fx-filterbar select{min-width:150px;max-width:100%;padding:9px 11px;border:1px solid #d7e2d9;border-radius:8px;background:#fff;color:#294635}
      .fx-workspace .fx-filter-count{font-size:11px;color:#718078;margin-left:auto}
      .fx-workspace .fx-modal-backdrop{position:fixed;inset:0;z-index:99999;background:rgba(13,34,22,.52);display:none;align-items:center;justify-content:center;padding:16px}
      .fx-workspace .fx-modal-backdrop.is-open{display:flex}
      .fx-workspace .fx-modal{width:min(680px,100%);max-height:90vh;overflow:auto;background:#f8fbf8;border:1px solid #cfe0d2;border-radius:16px;box-shadow:0 24px 80px #10271955}
      .fx-workspace .fx-modal-head{position:sticky;top:0;z-index:2;display:flex;justify-content:space-between;align-items:center;gap:12px;padding:15px 18px;background:#e8f3eb;border-bottom:1px solid #d3e4d7}
      .fx-workspace .fx-modal-head h3{margin:0;color:#194b2e;font-size:16px}
      .fx-workspace .fx-modal-close{width:34px;height:34px;border:0;border-radius:50%;background:#d7e9dc;color:#194b2e;font-size:22px;cursor:pointer}
      .fx-workspace .fx-modal-body{padding:16px}
      .fx-workspace .fx-modal-body .fx-form{margin:0;grid-template-columns:repeat(auto-fit,minmax(190px,1fr))}
      .fx-workspace .fx-modal-body .fx-form button{grid-column:1/-1;min-height:42px}
      .fx-workspace .fx-card>h2{display:flex;align-items:center;gap:8px;flex-wrap:wrap}
      .fx-workspace .fx-card>h2+ p{line-height:1.5}
      @media(max-width:560px){.fx-workspace .fx-modal-backdrop{padding:8px;align-items:flex-end}.fx-workspace .fx-modal{max-height:94vh;border-radius:16px 16px 10px 10px}.fx-workspace .fx-modal-body{padding:12px}.fx-workspace .fx-filterbar>*{flex:1 1 100%}.fx-workspace .fx-filter-count{margin-left:0}}
    </style>
    <script>
    (function(){
      function initFinanceWorkspace(){
        var root=document.querySelector('.fx-workspace');
        if(!root || root.dataset.fxEnhanced==='1') return;
        root.dataset.fxEnhanced='1';
        var modalLayer=document.createElement('div');
        modalLayer.className='fx-modal-backdrop';
        modalLayer.innerHTML="<section class='fx-modal' role='dialog' aria-modal='true' aria-labelledby='fxModalTitle'><header class='fx-modal-head'><h3 id='fxModalTitle'>Finance entry</h3><button type='button' class='fx-modal-close' aria-label='Close'>&times;</button></header><div class='fx-modal-body'></div></section>";
        root.appendChild(modalLayer);
        var modalBody=modalLayer.querySelector('.fx-modal-body');
        var modalTitle=modalLayer.querySelector('#fxModalTitle');
        var activeForm=null;var activePlaceholder=null;
        function closeModal(){modalLayer.classList.remove('is-open');if(activeForm&&activePlaceholder&&activePlaceholder.parentNode){activePlaceholder.parentNode.insertBefore(activeForm,activePlaceholder.nextSibling);}modalBody.innerHTML='';activeForm=null;activePlaceholder=null;}
        modalLayer.querySelector('.fx-modal-close').addEventListener('click',closeModal);
        modalLayer.addEventListener('click',function(e){if(e.target===modalLayer)closeModal();});
        document.addEventListener('keydown',function(e){if(e.key==='Escape')closeModal();});
        root.querySelectorAll('.fx-card form.fx-form').forEach(function(form,index){
          var card=form.closest('.fx-card');
          var heading=card&&card.querySelector('h2');
          var submit=form.querySelector("button[type='submit'],button:not([type])");
          var action=(submit&&submit.textContent.trim())||'Save';
          var title=(heading&&heading.textContent.trim())||'Finance entry';
          var placeholder=document.createComment('finance-form-location');
          form.parentNode.insertBefore(placeholder,form);
          var trigger=document.createElement('button');
          trigger.type='button';trigger.className='fx-open-modal';
          trigger.textContent=action;
          trigger.addEventListener('click',function(){
            if(activeForm)closeModal();
            modalTitle.textContent=title;
            modalBody.innerHTML='';
            activeForm=form;activePlaceholder=placeholder;
            modalBody.appendChild(form);
            modalLayer.classList.add('is-open');
            var first=modalBody.querySelector('input:not([type=hidden]),select,textarea');
            if(first)first.focus();
          });
          var slot=document.createElement('div');slot.className='fx-action-row';slot.appendChild(trigger);
          form.parentNode.insertBefore(slot,placeholder);
          form.remove();
        });
        root.querySelectorAll('.fx-table-wrap').forEach(function(wrap){
          var table=wrap.querySelector('table');if(!table)return;
          var head=table.querySelector('thead tr');var rows=Array.from(table.querySelectorAll('tbody tr'));
          if(!rows.length)return;
          var headers=head?Array.from(head.children).map(function(x){return x.textContent.trim().toLowerCase();}):[];
          var bar=document.createElement('div');bar.className='fx-filterbar';
          var search=document.createElement('input');search.type='search';search.placeholder='Search records…';search.setAttribute('aria-label','Search table records');
          bar.appendChild(search);
          var statusIndex=headers.findIndex(function(x){return x.indexOf('status')>=0||x==='match';});
          var statusSelect=null;
          if(statusIndex>=0){
            var vals=Array.from(new Set(rows.map(function(row){return (row.children[statusIndex]||{}).textContent.trim();}).filter(Boolean))).sort();
            if(vals.length){
              statusSelect=document.createElement('select');statusSelect.setAttribute('aria-label','Filter by status');
              statusSelect.innerHTML="<option value=''>All statuses</option>";
              vals.forEach(function(v){var o=document.createElement('option');o.value=v;o.textContent=v;statusSelect.appendChild(o);});
              bar.appendChild(statusSelect);
            }
          }
          var dateIndex=headers.findIndex(function(x){return x.indexOf('date')>=0;});
          var from=null,to=null;
          if(dateIndex>=0){
            from=document.createElement('input');from.type='date';from.setAttribute('aria-label','From date');
            to=document.createElement('input');to.type='date';to.setAttribute('aria-label','To date');
            bar.appendChild(from);bar.appendChild(to);
          }
          var count=document.createElement('span');count.className='fx-filter-count';bar.appendChild(count);
          wrap.parentNode.insertBefore(bar,wrap);
          function apply(){
            var q=search.value.trim().toLowerCase(),st=statusSelect?statusSelect.value:'',shown=0;
            rows.forEach(function(row){
              var cells=Array.from(row.children);
              var matchText=!q||row.textContent.toLowerCase().indexOf(q)>=0;
              var dateCell=dateIndex>=0&&cells[dateIndex]?cells[dateIndex].textContent.trim().slice(0,10):'';
              var matchStatus=!st||(cells[statusIndex]&&cells[statusIndex].textContent.trim()===st);
              var matchFrom=!from||!from.value||!dateCell||dateCell>=from.value;
              var matchTo=!to||!to.value||!dateCell||dateCell<=to.value;
              var visible=matchText&&matchStatus&&matchFrom&&matchTo;
              row.style.display=visible?'':'none';if(visible)shown++;
            });
            count.textContent=shown+' of '+rows.length+' records';
          }
          [search,statusSelect,from,to].filter(Boolean).forEach(function(el){el.addEventListener('input',apply);el.addEventListener('change',apply);});
          apply();
        });
      }
      if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',initFinanceWorkspace);else initFinanceWorkspace();
    })();
    </script>
    """


def _finance_tabs(active):
    items = [
        ("overview","Overview","/app/finance"),("billing","Fees & Billing","/app/finance/billing"),
        ("collections","Collections & Receipting","/app/finance/collections"),
        ("payables","Accounts Payable","/app/finance/payables"),
        ("ledger","General Accounting","/app/finance/ledger"),
        ("banking","Cash & Banking","/app/finance/banking"),
        ("budgets","Budgets & Planning","/app/finance/budgets"),
        ("reports","Financial Reports","/app/finance/reports")
    ]
    return "<nav class='fx-tabs' aria-label='Finance and Accounts workspaces'>" + "".join(
        "<a class='%s' href='%s'>%s</a>" % ("active" if key==active else "",url,label)
        for key,label,url in items
    ) + "</nav>"


def _finance_table(headers, rows, empty):
    head = "".join("<th>%s</th>" % escape(str(h)) for h in headers)
    body = rows or "<tr><td colspan='%s' class='fx-empty'>%s</td></tr>" % (max(1,len(headers)),escape(empty))
    return "<div class='fx-table-wrap'><table><thead><tr>%s</tr></thead><tbody>%s</tbody></table></div>" % (head,body)


def _finance_cell(value):
    return escape(str(value if value is not None else ""))


@router.get("/app/finance/{section}", response_class=HTMLResponse)
def finance_workspace_section(request: Request, section: str):
    sid = _finance_access(request)
    if not sid:
        return RedirectResponse("/",303)
    allowed = {"billing","collections","payables","ledger","banking","budgets","reports"}
    if section not in allowed:
        return RedirectResponse("/app/finance",303)
    con = _db()
    try:
        cur = con.cursor()
        _finance_prepare(cur,sid)
        title = {
            "billing":"Fees & Billing","collections":"Collections & Receipting",
            "payables":"Accounts Payable","ledger":"General Accounting",
            "banking":"Cash & Banking","budgets":"Budgets & Planning",
            "reports":"Financial Reports"
        }[section]
        content = ""
        if section == "billing":
            charges = cur.execute("""SELECT f.id,f.amount,f.paid,f.status,f.description,f.due_date,
                s.name student_name,s.admission_no FROM fees f JOIN students s ON s.id=f.student_id
                AND s.school_id=f.school_id WHERE f.school_id=? ORDER BY f.id DESC LIMIT 250""",(sid,)).fetchall()
            students = cur.execute("SELECT id,name,admission_no FROM students WHERE school_id=? AND lower(COALESCE(status,'active')) NOT IN ('inactive','transferred','graduated') ORDER BY name",(sid,)).fetchall()
            opts = "".join("<option value='%s'>%s (%s)</option>"%(int(x["id"]),_finance_cell(x["name"]),_finance_cell(x["admission_no"])) for x in students)
            rows = "".join("<tr><td>%s</td><td>%s</td><td>KES %.2f</td><td>KES %.2f</td><td>KES %.2f</td><td>%s</td><td>%s</td></tr>"%(
                _finance_cell(x["student_name"]),_finance_cell(x["admission_no"]),float(x["amount"] or 0),
                float(x["paid"] or 0),max(0,float(x["amount"] or 0)-float(x["paid"] or 0)),
                _finance_cell(x["status"] or "Pending"),_finance_cell(x["due_date"] or "")) for x in charges)
            content = """<div class='fx-card'><h2>Create learner charge</h2><p>Charges are attached to the learner record and appear in their running fee balance.</p>
            <form method='post' action='/app/finance/billing/charge' class='fx-form'>
            <select name='student_id' required><option value=''>Select learner</option>%s</select>
            <input name='description' required placeholder='Charge description / fee item'>
            <input name='amount' type='number' min='0.01' step='0.01' required placeholder='Amount (KES)'>
            <input name='due_date' type='date'><button type='submit'>Create charge</button></form></div>
            <div class='fx-card'><h2>Fee accounts</h2>%s</div>""" % (opts,_finance_table(["Learner","Admission No.","Billed","Paid","Balance","Status","Due date"],rows,"No fee charges recorded."))
        elif section == "collections":
            payments = cur.execute("""SELECT p.id,p.amount,p.reference,p.method,p.date,p.received_by,s.name learner
                FROM fee_payments p LEFT JOIN students s ON s.id=p.student_id AND s.school_id=p.school_id
                WHERE p.school_id=? ORDER BY p.id DESC LIMIT 300""",(sid,)).fetchall()
            students = cur.execute("SELECT id,name,admission_no FROM students WHERE school_id=? AND lower(COALESCE(status,'active')) NOT IN ('inactive','transferred','graduated') ORDER BY name",(sid,)).fetchall()
            opts = "".join("<option value='%s'>%s (%s)</option>"%(int(x["id"]),_finance_cell(x["name"]),_finance_cell(x["admission_no"])) for x in students)
            rows = "".join("<tr><td>RCP-%s</td><td>%s</td><td>KES %.2f</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td></tr>"%(
                int(x["id"]),_finance_cell(x["learner"]),float(x["amount"] or 0),_finance_cell(x["method"]),
                _finance_cell(x["reference"]),_finance_cell(x["date"]),_finance_cell(x["received_by"])) for x in payments)
            content = """<div class='fx-card'><h2>Receive payment</h2><p>Payments are allocated against the learner's oldest outstanding charges. Overpayments are rejected.</p>
            <form method='post' action='/app/finance/collections/receive' class='fx-form'>
            <select name='student_id' required><option value=''>Select learner</option>%s</select>
            <input name='amount' type='number' min='0.01' step='0.01' required placeholder='Amount (KES)'>
            <select name='method'><option>Cash</option><option>Bank</option><option>Mobile Money</option><option>Cheque</option><option>Card</option><option>Other</option></select>
            <input name='reference' placeholder='M-Pesa / bank / receipt reference'><button type='submit'>Record & issue receipt</button></form></div>
            <div class='fx-card'><h2>Receipt register</h2>%s</div>"""%(opts,_finance_table(["Receipt No.","Learner","Amount","Method","Reference","Date","Received by"],rows,"No payments recorded."))
        elif section == "payables":
            suppliers = cur.execute("SELECT * FROM ds_fin_suppliers WHERE school_id=? ORDER BY name",(sid,)).fetchall()
            bills = cur.execute("""SELECT b.*,s.name supplier_name FROM ds_fin_bills b
                JOIN ds_fin_suppliers s ON s.id=b.supplier_id AND s.school_id=b.school_id
                WHERE b.school_id=? ORDER BY b.id DESC LIMIT 200""",(sid,)).fetchall()
            sopts = "".join("<option value='%s'>%s</option>"%(x["id"],_finance_cell(x["name"])) for x in suppliers)
            sr = "".join("<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td></tr>"%(_finance_cell(x["name"]),_finance_cell(x["phone"]),_finance_cell(x["email"]),_finance_cell(x["tax_pin"])) for x in suppliers)
            br = "".join("<tr><td>%s</td><td>%s</td><td>%s</td><td>KES %.2f</td><td>%s</td><td>%s</td></tr>"%(
                _finance_cell(x["supplier_name"]),_finance_cell(x["invoice_no"]),_finance_cell(x["due_date"]),
                float(x["amount"] or 0),_finance_cell(x["status"]),(
                    "<form method='post' action='/app/finance/payables/pay'><input type='hidden' name='bill_id' value='%s'><button>Mark paid</button></form>"%x["id"]
                    if x["status"]=="Approved" else ("<form method='post' action='/app/finance/payables/approve'><input type='hidden' name='bill_id' value='%s'><button>Approve</button></form>"%x["id"] if x["status"]=="Draft" else ""))) for x in bills)
            content = """<div class='fx-two'><div class='fx-card'><h2>Supplier register</h2><form method='post' action='/app/finance/payables/supplier' class='fx-form'>
            <input name='name' required placeholder='Supplier name'><input name='phone' placeholder='Phone'><input name='email' type='email' placeholder='Email'><input name='tax_pin' placeholder='KRA PIN'><button>Add supplier</button></form>%s</div>
            <div class='fx-card'><h2>Supplier invoice / bill</h2><form method='post' action='/app/finance/payables/bill' class='fx-form'>
            <select name='supplier_id' required><option value=''>Select supplier</option>%s</select><input name='invoice_no' required placeholder='Supplier invoice no.'>
            <input name='bill_date' type='date' required><input name='due_date' type='date'><input name='description' placeholder='Description'>
            <input name='amount' type='number' min='0.01' step='0.01' required placeholder='Amount (KES)'><button>Create draft bill</button></form></div></div>
            <div class='fx-card'><h2>Supplier directory</h2>%s</div><div class='fx-card'><h2>Payables register</h2><p>Draft bills must be approved before payment. Payment is recorded in the cashbook and expense register.</p>%s</div>"""%(
                _finance_table(["Supplier","Phone","Email","KRA PIN"],sr,"No suppliers yet."),sopts,
                _finance_table(["Supplier","Phone","Email","KRA PIN"],sr,"No suppliers yet."),
                _finance_table(["Supplier","Invoice","Due date","Amount","Status","Action"],br,"No supplier bills yet."))
            content = "<div class='fx-payables-page'>" + content + "</div>"
        elif section == "ledger":
            accounts = cur.execute("SELECT * FROM ds_fin_accounts WHERE school_id=? AND active=1 ORDER BY code",(sid,)).fetchall()
            journals = cur.execute("SELECT * FROM ds_fin_journals WHERE school_id=? ORDER BY created_at DESC LIMIT 100",(sid,)).fetchall()
            ar = "".join("<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>KES %.2f</td></tr>"%(
                _finance_cell(x["code"]),_finance_cell(x["name"]),_finance_cell(x["account_type"]),
                "Active" if x["active"] else "Inactive",float(x["opening_balance"] or 0)) for x in accounts)
            jr = "".join("<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>%s</td></tr>"%(
                _finance_cell(x["journal_date"]),_finance_cell(x["reference"]),_finance_cell(x["description"]),
                _finance_cell(x["status"]),(
                    "<form method='post' action='/app/finance/ledger/post'><input type='hidden' name='journal_id' value='%s'><button>Post</button></form>"%x["id"]
                    if x["status"]=="Draft" else ("Reversed" if x["status"]=="Reversed" else "<form method='post' action='/app/finance/ledger/reverse'><input type='hidden' name='journal_id' value='%s'><input name='reason' required placeholder='Reversal reason'><button>Reverse</button></form>"%x["id"])),
                _finance_cell(x["created_by"])) for x in journals)
            opts = "".join("<option value='%s'>%s · %s</option>"%(_finance_cell(x["code"]),_finance_cell(x["code"]),_finance_cell(x["name"])) for x in accounts)
            content = """<div class='fx-card'><h2>Chart of accounts</h2><p>Starter school chart. Additions are school-specific and do not change existing records.</p>%s
            <form method='post' action='/app/finance/ledger/account' class='fx-form'><input name='code' required placeholder='Account code'><input name='name' required placeholder='Account name'>
            <select name='account_type'><option>Asset</option><option>Liability</option><option>Equity</option><option>Income</option><option>Expense</option></select><input name='opening_balance' type='number' step='0.01' value='0' placeholder='Opening balance'><button>Add account</button></form></div>
            <div class='fx-card'><h2>New balanced journal</h2><p>Enter equal debit and credit values. Journals remain drafts until explicitly posted.</p>
            <form method='post' action='/app/finance/ledger/journal' class='fx-form'><input name='journal_date' type='date' required><input name='reference' placeholder='Reference'>
            <input name='description' required placeholder='Journal description'><select name='debit_account' required><option value=''>Debit account</option>%s</select>
            <select name='credit_account' required><option value=''>Credit account</option>%s</select><input name='amount' type='number' min='0.01' step='0.01' required placeholder='Amount (KES)'><button>Save draft journal</button></form></div>
            <div class='fx-card'><h2>Journal register</h2>%s</div>"""%(_finance_table(["Code","Account","Type","Status","Opening balance"],ar,"No accounts."),
                opts,opts,_finance_table(["Date","Reference","Description","Status","Posted at","Created by"],jr,"No journals yet."))
            periods=cur.execute("SELECT period_start,period_end,status FROM ds_fin_periods WHERE school_id=? ORDER BY period_start DESC LIMIT 20",(sid,)).fetchall()
            period_rows="".join("<tr><td>%s</td><td>%s</td><td>%s</td></tr>"%(_finance_cell(x["period_start"]),_finance_cell(x["period_end"]),_finance_cell(x["status"])) for x in periods)
            content += "<div class='fx-card'><h2>Close accounting period</h2><p>Closing a period prevents new charges, receipts and journals dated inside that period. Ensure bank reconciliation and approvals are complete first.</p><form method='post' action='/app/finance/periods/close' class='fx-form'><input type='date' name='period_start' required><input type='date' name='period_end' required><button>Close period</button></form>"+_finance_table(["Period start","Period end","Status"],period_rows,"No accounting periods locked.")+"</div>"
        elif section == "banking":
            banks = cur.execute("SELECT * FROM ds_fin_bank_accounts WHERE school_id=? ORDER BY bank_name",(sid,)).fetchall()
            lines = cur.execute("""SELECT l.*,b.bank_name,b.account_name FROM ds_fin_bank_lines l
                JOIN ds_fin_bank_accounts b ON b.id=l.account_id AND b.school_id=l.school_id
                WHERE l.school_id=? ORDER BY l.line_date DESC LIMIT 250""",(sid,)).fetchall()
            opts = "".join("<option value='%s'>%s · %s</option>"%(x["id"],_finance_cell(x["bank_name"]),_finance_cell(x["account_name"])) for x in banks)
            br = "".join("<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td><td>KES %.2f</td><td>%s</td><td>%s</td></tr>"%(
                _finance_cell(x["bank_name"]),_finance_cell(x["line_date"]),_finance_cell(x["reference"]),
                _finance_cell(x["description"]),float(x["amount"] or 0),_finance_cell(x["direction"]),
                "Reconciled" if x["reconciled"] else "<form method='post' action='/app/finance/banking/reconcile'><input type='hidden' name='line_id' value='%s'><button>Match cashbook</button></form>"%x["id"]) for x in lines)
            content = """<div class='fx-two'><div class='fx-card'><h2>Bank / cash account</h2><form method='post' action='/app/finance/banking/account' class='fx-form'>
            <input name='bank_name' required placeholder='Bank / M-Pesa / Cash'><input name='account_name' required placeholder='Account name'><input name='account_number' placeholder='Account number (optional)'>
            <input name='opening_balance' type='number' step='0.01' value='0' placeholder='Opening balance'><button>Add account</button></form></div>
            <div class='fx-card'><h2>Statement line entry</h2><p>Enter or import statement lines, then match them to recorded cashbook transactions.</p>
            <form method='post' action='/app/finance/banking/line' class='fx-form'><select name='account_id' required><option value=''>Select account</option>%s</select>
            <input name='line_date' type='date' required><input name='reference' placeholder='Bank reference'><input name='description' placeholder='Description'>
            <input name='amount' type='number' min='0.01' step='0.01' required placeholder='Amount'><select name='direction'><option>Credit</option><option>Debit</option></select><button>Add statement line</button></form></div></div>
            <div class='fx-card'><h2>Import bank statement (CSV)</h2><p>CSV headers: Date, Reference, Description, Amount, Direction. Alternatively use Date, Debit, Credit. Duplicate rows are skipped.</p>
            <form method='post' enctype='multipart/form-data' action='/app/finance/banking/import' class='fx-form'><select name='account_id' required><option value=''>Select account</option>%s</select><input type='file' name='statement_file' accept='.csv,text/csv' required><button>Import statement</button></form></div>
            <div class='fx-card'><h2>Reconciliation register</h2>%s</div>"""%(opts,opts,_finance_table(["Account","Date","Reference","Description","Amount","Direction","Match"],br,"No statement lines."))
        elif section == "budgets":
            budgets = cur.execute("SELECT * FROM ds_fin_budgets WHERE school_id=? ORDER BY budget_year DESC,department",(sid,)).fetchall()
            actuals = cur.execute("SELECT category,COALESCE(SUM(amount),0) actual FROM expenses WHERE school_id=? GROUP BY category",(sid,)).fetchall()
            actual_map = {str(x["category"] or "").strip().lower():float(x["actual"] or 0) for x in actuals}
            rows = "".join("<tr><td>%s</td><td>%s</td><td>KES %.2f</td><td>KES %.2f</td><td>KES %.2f</td></tr>"%(
                _finance_cell(x["budget_year"]),_finance_cell(x["department"]),float(x["amount"] or 0),
                actual_map.get(str(x["department"] or "").strip().lower(),0),
                float(x["amount"] or 0)-actual_map.get(str(x["department"] or "").strip().lower(),0)) for x in budgets)
            content = """<div class='fx-card'><h2>Annual / departmental budget</h2><form method='post' action='/app/finance/budgets/add' class='fx-form'>
            <input name='budget_year' required placeholder='Financial year e.g. 2027'><input name='department' required placeholder='Department / expense category'>
            <input name='account_code' placeholder='Account code (optional)'><input name='amount' type='number' min='0.01' step='0.01' required placeholder='Budget amount (KES)'><button>Save budget</button></form></div>
            <div class='fx-card'><h2>Budget vs recorded expenditure</h2><p>Actuals are matched to the existing expense category field.</p>%s</div>"""%_finance_table(["Year","Department","Budget","Recorded actual","Variance"],rows,"No budgets created.")
        else:
            start_day=str(request.query_params.get("from") or datetime.now(ZoneInfo("Africa/Nairobi")).strftime("%Y-01-01"))[:10]
            end_day=str(request.query_params.get("to") or datetime.now(ZoneInfo("Africa/Nairobi")).strftime("%Y-%m-%d"))[:10]
            accounts = cur.execute("""SELECT a.code,a.name,a.account_type,a.opening_balance,
                COALESCE(SUM(CASE WHEN j.id IS NOT NULL THEN l.debit ELSE 0 END),0) debits,COALESCE(SUM(CASE WHEN j.id IS NOT NULL THEN l.credit ELSE 0 END),0) credits
                FROM ds_fin_accounts a LEFT JOIN ds_fin_journal_lines l ON l.school_id=a.school_id AND l.account_code=a.code
                LEFT JOIN ds_fin_journals j ON j.id=l.journal_id AND j.school_id=l.school_id AND j.status IN ('Posted','Reversed') AND j.journal_date BETWEEN ? AND ?
                WHERE a.school_id=? AND a.active=1 GROUP BY a.code,a.name,a.account_type,a.opening_balance ORDER BY a.code""",(start_day,end_day,sid)).fetchall()
            tb_rows=[];income=0.0;expenses_total=0.0;assets=0.0;liabilities=0.0;equity=0.0;cash_net=0.0
            for acc in accounts:
                debit=float(acc["debits"] or 0);credit=float(acc["credits"] or 0);opening=float(acc["opening_balance"] or 0)
                kind=str(acc["account_type"] or "")
                balance=opening+debit-credit if kind in ("Asset","Expense") else opening+credit-debit
                dr=max(0,balance) if kind in ("Asset","Expense") else 0
                cr=max(0,-balance) if kind in ("Asset","Expense") else max(0,balance)
                tb_rows.append("<tr><td>%s</td><td>%s</td><td>%s</td><td>KES %.2f</td><td>KES %.2f</td></tr>"%(_finance_cell(acc["code"]),_finance_cell(acc["name"]),_finance_cell(kind),dr,cr))
                if kind=="Income":income+=credit-debit
                elif kind=="Expense":expenses_total+=debit-credit
                elif kind=="Asset":assets+=balance
                elif kind=="Liability":liabilities+=balance
                elif kind=="Equity":equity+=balance
                if str(acc["code"]) in ("1000","1010","1020"):cash_net+=debit-credit
            surplus=income-expenses_total
            statement_rows="<tr><td>Income</td><td>KES %.2f</td></tr><tr><td>Expenses</td><td>KES %.2f</td></tr><tr><td>Net surplus / (deficit)</td><td>KES %.2f</td></tr>"%(income,expenses_total,surplus)
            position_rows="<tr><td>Assets</td><td>KES %.2f</td></tr><tr><td>Liabilities</td><td>KES %.2f</td></tr><tr><td>Accumulated funds</td><td>KES %.2f</td></tr><tr><td>Current period surplus / (deficit)</td><td>KES %.2f</td></tr><tr><td>Total liabilities and funds</td><td>KES %.2f</td></tr>"%(assets,liabilities,equity,surplus,liabilities+equity+surplus)
            cash_rows="<tr><td>Net movement in cash, bank and mobile-money control accounts</td><td>KES %.2f</td></tr>"%cash_net
            closed=cur.execute("SELECT period_start,period_end,closed_by,closed_at FROM ds_fin_periods WHERE school_id=? AND status='Closed' ORDER BY period_start DESC LIMIT 20",(sid,)).fetchall()
            closed_rows="".join("<tr><td>%s</td><td>%s</td><td>%s</td><td>%s</td></tr>"%(_finance_cell(x["period_start"]),_finance_cell(x["period_end"]),_finance_cell(x["closed_by"]),_finance_cell(x["closed_at"])) for x in closed)
            content="""<div class='fx-card'><h2>Financial statement period</h2><form method='get' action='/app/finance/reports' class='fx-form'><input type='date' name='from' value='%s'><input type='date' name='to' value='%s'><button>Run statements</button></form><p>Statements are calculated from posted double-entry journals and account opening balances for the selected period.</p></div>
            <div class='fx-kpis'><div><small>Total income</small><b>KES %.2f</b></div><div><small>Total expenses</small><b>KES %.2f</b></div><div><small>Net surplus / (deficit)</small><b>KES %.2f</b></div><div><small>Assets</small><b>KES %.2f</b></div></div>
            <div class='fx-card'><h2>Trial balance</h2>%s</div>
            <div class='fx-two'><div class='fx-card'><h2>Income statement</h2>%s</div><div class='fx-card'><h2>Statement of financial position</h2>%s</div></div>
            <div class='fx-card'><h2>Cash flow summary</h2>%s</div>
            <div class='fx-card'><h2>Accounting period locks</h2><p>Closed periods block new ledger postings and manual journal posting within their date range. Close only after reconciliation and review.</p>%s</div>"""%(escape(start_day),escape(end_day),income,expenses_total,surplus,assets,
                _finance_table(["Code","Account","Type","Debit balance","Credit balance"],"".join(tb_rows),"No posted ledger entries for this period."),
                _finance_table(["Description","Amount"],statement_rows,"No statement values."),
                _finance_table(["Position","Amount"],position_rows,"No position values."),
                _finance_table(["Cash flow measure","Amount"],cash_rows,"No cash movement."),
                _finance_table(["Period start","Period end","Closed by","Closed at"],closed_rows,"No periods closed."))
        con.commit()
    finally:
        con.close()
    content += _finance_interaction_enhancements()
    # The page template below uses %-formatting; escape percent signs in dynamic
    # workspace HTML (including CSS widths) so they remain literal in the output.
    body_template = """<div class='page fx-workspace'><div class='fx-heading'><div><div class='fx-eyebrow'>SCHOOL FINANCIAL CONTROL · KES</div><h1>%s</h1><p>Connected financial records with school-level access and audit history.</p></div><a class='fx-back' href='/app/finance'>Finance overview</a></div>%s%s</div>
    <style>
    .fx-heading{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:14px}
    .fx-eyebrow{font-size:11px;letter-spacing:1.2px;color:#27734c;font-weight:800}
    .fx-heading h1{margin:5px 0;font-size:26px}.fx-heading p{margin:0;color:#718078;font-size:13px}
    .fx-back{color:#246b45;font-weight:800;text-decoration:none}
    .fx-tabs{display:flex;gap:8px;flex-wrap:wrap;margin:16px 0 20px}
    .fx-tabs a{padding:10px 13px;border:1px solid #dce8df;border-radius:9px;background:#fff;color:#315342;text-decoration:none;font-size:12px;font-weight:750}
    .fx-tabs a.active,.fx-tabs a:hover{background:#e8f3eb;border-color:#74a88a;color:#185333}
    .fx-card{background:#fff;border:1px solid #e2eae3;border-radius:13px;padding:16px;margin:12px 0;box-shadow:0 3px 12px #193d2610}
    .fx-card h2{font-size:17px;margin:0 0 8px;color:#254d36}.fx-card p{font-size:12px;color:#718078;margin:0 0 12px}
    .fx-form{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:9px;margin:10px 0 14px}
    .fx-form input,.fx-form select{min-width:0;width:100%%;padding:11px;border:1px solid #d7e2d9;border-radius:8px;background:#fff;color:#243b2c}
    .fx-form button,.fx-table-wrap button{border:0;border-radius:8px;padding:10px 13px;background:#236b45;color:#fff;font-weight:800;cursor:pointer}
    .fx-table-wrap{overflow:auto;width:100%%}.fx-table-wrap table{width:100%%;border-collapse:collapse;font-size:12px;min-width:650px}
    .fx-table-wrap th,.fx-table-wrap td{padding:10px;border-bottom:1px solid #edf1ed;text-align:left;white-space:nowrap}
    .fx-table-wrap th{color:#315342;background:#f6faf6;font-weight:800}.fx-empty{text-align:center;color:#829087;padding:20px!important}
    .fx-two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}
    .fx-payables-page{width:100%;max-width:1080px;min-width:0;margin:0 auto;box-sizing:border-box}
    .fx-payables-page .fx-card{min-width:0;box-sizing:border-box}
    .fx-payables-page .fx-table-wrap{width:100%;max-width:100%;overflow-x:auto;-webkit-overflow-scrolling:touch;overscroll-behavior-x:contain;touch-action:pan-x pan-y}
    .fx-payables-page .fx-form{min-width:0}
    .fx-kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:10px;margin:12px 0}
    .fx-kpis>div{background:#fff;border:1px solid #e2eae3;border-radius:12px;padding:14px;display:grid;gap:7px}
    .fx-kpis small{color:#718078;font-size:12px}.fx-kpis b{font-size:19px;color:#214d34}
    @media(max-width:700px){.fx-two{grid-template-columns:1fr}.fx-heading h1{font-size:22px}.fx-tabs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}}
    </style>"""
    # Protect interpolation slots, then escape every literal percent sign in
    # the static template (including CSS widths and media-query percentages).
    _slot = "\uE000"
    _percent = "\uE001"
    body_template = (body_template.replace("%%", _percent)
                     .replace("%s", _slot).replace("%", "%%")
                     .replace(_percent, "%%").replace(_slot, "%s"))
    body = body_template % (escape(title), "", content)
    return _school_page(request,title,body)


@router.post("/app/finance/billing/charge")
def finance_billing_charge(request: Request, student_id:int=Form(...), description:str=Form(...), amount:float=Form(...), due_date:str=Form("")):
    sid=_finance_access(request)
    if not sid:return RedirectResponse("/",303)
    if amount<=0 or not description.strip():return HTMLResponse("Enter a valid description and positive amount.",400)
    con=_db();cur=con.cursor()
    student=cur.execute("SELECT id FROM students WHERE id=? AND school_id=?",(student_id,sid)).fetchone()
    if not student:con.close();return HTMLResponse("Learner not found in this school.",404)
    _finance_prepare(cur,sid)
    day=datetime.now(ZoneInfo("Africa/Nairobi")).strftime("%Y-%m-%d")
    if not _finance_period_open(cur,sid,day):
        con.close();return HTMLResponse("The current accounting period is closed.",409)
    cur.execute("INSERT INTO fees(school_id,student_id,amount,paid,description,due_date,status) VALUES(?,?,?,?,?,?,?)",
                (sid,student_id,amount,0,description.strip(),due_date or None,"Pending"))
    fee_id=cur.lastrowid
    _finance_post_source(cur,sid,day,"FEE-"+str(fee_id),"Learner fee charge: "+description.strip(),"1100","4000",amount,str(request.session.get("email","")),"fee_charge",fee_id)
    _audit(cur,sid,request,"FEE_CHARGE", "Created fee charge %s for learner %s"%(amount,student_id))
    con.commit();con.close()
    return RedirectResponse("/app/finance/billing",303)


@router.post("/app/finance/collections/receive")
def finance_collections_receive(request: Request, student_id:int=Form(...), amount:float=Form(...), method:str=Form("Cash"), reference:str=Form("")):
    sid=_finance_access(request)
    if not sid:return RedirectResponse("/",303)
    if amount<=0:return HTMLResponse("Payment must be greater than zero.",400)
    con=_db();cur=con.cursor();_finance_prepare(cur,sid)
    if not cur.execute("SELECT id FROM students WHERE id=? AND school_id=?",(student_id,sid)).fetchone():
        con.close();return HTMLResponse("Learner not found in this school.",404)
    charges=cur.execute("SELECT id,amount,paid FROM fees WHERE school_id=? AND student_id=? AND COALESCE(amount,0)>COALESCE(paid,0) ORDER BY id",(sid,student_id)).fetchall()
    outstanding=sum(max(0,float(x["amount"] or 0)-float(x["paid"] or 0)) for x in charges)
    if outstanding<=0 or amount>outstanding:
        con.close();return HTMLResponse("Payment must not exceed the learner's outstanding balance (KES %.2f)."%outstanding,400)
    day=datetime.now(ZoneInfo("Africa/Nairobi")).strftime("%Y-%m-%d")
    if not _finance_period_open(cur,sid,day):
        con.close();return HTMLResponse("The current accounting period is closed.",409)
    cur.execute("INSERT INTO fee_payments(school_id,student_id,amount,reference,method,date,received_by) VALUES(?,?,?,?,?,?,?)",
                (sid,student_id,amount,reference.strip(),method.strip() or "Cash",day,str(request.session.get("email",""))))
    payment_id=cur.lastrowid
    pay_method=(method or "Cash").lower()
    debit_code="1020" if "mobile" in pay_method or "mpesa" in pay_method else ("1010" if any(x in pay_method for x in ("bank","cheque","card")) else "1000")
    _finance_post_source(cur,sid,day,reference.strip() or "RCP-"+str(payment_id),"Learner fee payment",debit_code,"1100",amount,str(request.session.get("email","")),"fee_payment",payment_id)
    remaining=amount
    for item in charges:
        if remaining<=0:break
        balance=max(0,float(item["amount"] or 0)-float(item["paid"] or 0))
        applied=min(remaining,balance);new_paid=float(item["paid"] or 0)+applied;remaining-=applied
        cur.execute("UPDATE fees SET paid=?,status=? WHERE id=? AND school_id=?",
                    (new_paid,"Paid" if new_paid>=float(item["amount"] or 0) else "Partial",item["id"],sid))
    cur.execute("INSERT INTO cashbook(school_id,date,reference,description,debit,credit,account) VALUES(?,?,?,?,?,?,?)",
                (sid,day,reference.strip(),"School fee receipt",0,amount,"Fees"))
    _audit(cur,sid,request,"FEE_PAYMENT","Received KES %.2f for learner %s"%(amount,student_id))
    con.commit();con.close()
    return RedirectResponse("/app/finance/collections",303)


